local config = {
  ui_story_5032_50320101_1_dialog_content = "<color=#e8d9bb>PlayerName, Vice, and Carleen, who is feeling lost in the pursuit of power, are heading to the bustling port of Harbor City.</color>",
  ui_story_5032_50320101_2_dialog_content = "<color=#e8d9bb>On their way to visit Laird Elvis, the Caelestite once again meets Fia, the extrozoologist.</color>",
  ui_story_5032_50320101_3_dialog_content = "<color=#e8d9bb>Laird Elvis warmly welcomes the group, but he seems to be hiding something beneath his frail body and scarred face.</color>",
  ui_story_5032_50320101_4_dialog_content = "<color=#e8d9bb>A twist of fate brings the group to the Emerald, a ship where a grand festival is being held.</color>",
  ui_story_5032_50320101_5_dialog_content = "<color=#e8d9bb>Here, PlayerName and others meet Jeno, the mysterious and distant ringmaster.</color>",
  ui_story_5032_50320101_6_dialog_content = "<color=#e8d9bb>The cheerful and enthusiastic Rainbow, who is the circus emcee, customer liaison, security director, and marine engineer apprentice.</color>",
  ui_story_5032_50320101_7_dialog_content = "<color=#e8d9bb>And the three thrilling high-flying trapeze artists, Merylt, Subli, and Frimet.</color>",
  ui_story_5032_50320101_8_dialog_content = "<color=#e8d9bb>Fia is convinced that the wondrous beast she is in search of, a <color=#FFB400>Cloudwhale</color>, is somewhere on board the Emerald.</color>",
  ui_story_5032_50320101_9_dialog_content = "<color=#e8d9bb>To find out if she is right, squad Caelestite decides to sign up for a competition and buy more time to explore the circus.</color>",
  ui_story_5032_50320101_10_dialog_content = "<color=#e8d9bb>Meanwhile, Carleen, still feeling lost, asks Vice how she can become stronger.</color>",
  ui_story_5032_50320101_11_dialog_content = "<color=#e8d9bb>The Emerald is filled with joy and laughter, but Laird Elvis, who sits among the judges, is lost in thought.</color>",
  ui_story_5032_50320101_12_dialog_content = "<color=#e8d9bb>Frustrated during the competition, Carleen gains some new insights thanks to PlayerName's encouragement.</color>",
  ui_story_5032_50320101_13_dialog_content = "<color=#e8d9bb>Ultimately, squad Caelestite is victorious. But the prize is not a Cloudwhale.</color>",
  ui_story_5032_50320101_14_dialog_content = "<color=#e8d9bb>Instead, the prize is Kyllo, Fia's wondrous beast companion, which she had sent to search nearby waters for Cloudwhale.</color>",
  ui_story_5032_50320101_15_dialog_content = "<color=#e8d9bb>Disappointed, the group prepares to bid Jeno farewell and continue their search for Cloudwhale.</color>",
  ui_story_5032_50320101_16_dialog_content = "<color=#e8d9bb>But when they look for Jeno, they find him passing out in the cabin of the Emerald.</color>",
  ui_story_5032_50320101_17_dialog_content = "<color=#e8d9bb>Just as they manage to wake him, the ship shakes violently.</color>",
  ui_story_5032_50320101_18_dialog_content = "<color=#e8d9bb>Jeno guides the team as they rush to the Emerald's core chamber.</color>",
  ui_story_5032_50320101_19_dialog_content = "<color=#e8d9bb>But on the way, guards bearing the seal of the Elvis family block their passage.</color>",
  ui_story_5032_50320101_20_dialog_content = "<color=#e8d9bb>After overcoming various obstacles, the Caelestite's group reaches the core chamber and finally finds Elvis there.</color>",
  ui_story_5032_50320101_21_dialog_content = "<color=#e8d9bb>And he is using some device in his staff to absorb power from the energy core.</color>",
  ui_story_5032_50320101_22_dialog_content = "<color=#e8d9bb>Such action awakens the huge machine guarding the core, which begins to attack the group.</color>",
  ui_story_5032_50320101_23_dialog_content = "<color=#e8d9bb>The powerful Guardian pushes team Colossus to the brink of defeat. Even Carleen is immobilized by Elvis's trap.</color>",
  ui_story_5032_50320101_24_dialog_content = "<color=#e8d9bb>But at a decisive moment, a new power awakens within Carleen, pushing back the Guardian.</color>",
  ui_story_5032_50320101_25_dialog_content = "<color=#e8d9bb>The group defeats the Guardian, but Elvis escapes—only to be caught by Matthieu, a Lumopolis judge.</color>",
  ui_story_5032_50320101_26_dialog_content = "<color=#e8d9bb>But it seems this whole thing... is far from over.</color>",
  ui_story_5032_50320101_27_dialog_content = "<color=#e8d9bb>Air roars in the cold rain, and the sky ignites in the wild wind. A storm that will tear Harbor City apart is coming!</color>",
  ui_story_5032_50320101_28_dialog_content = "Quick, quick! The view from over here is awesome!",
  ui_story_5032_50320101_29_dialog_content = "E-Elvis! You're running too fast!",
  ui_story_5032_50320101_30_dialog_content = "Wow...",
  ui_story_5032_50320101_31_dialog_content = "How about that? You don't get to see this kind of view staying at home.",
  ui_story_5032_50320101_32_dialog_content = "Don't worry about those trouble-making little thugs. I can handle them and more.",
  ui_story_5032_50320101_33_dialog_content = "This beach, this ocean—one day it will all belong to you and me.",
  ui_story_5032_50320101_34_dialog_content = "Yeah!",
  ui_story_5032_50320101_35_dialog_content = "Sometimes I dream of doing this. Getting out of my room and painting the world outside.",
  ui_story_5032_50320101_36_dialog_content = "Maybe... Maybe I should paint this moment of ours.",
  ui_story_5032_50320101_37_dialog_content = "Really? You'd paint me?",
  ui_story_5032_50320101_38_dialog_content = "Yeah, but I'm slow and not very good at it, either.",
  ui_story_5032_50320101_39_dialog_content = "It's okay. Your drawings are the best to me!",
  ui_story_5032_50320101_40_dialog_content = "So... why don't we meet early tomorrow at the port?",
  ui_story_5032_50320101_41_dialog_content = "We can gather some seafood from the beach. Then you can paint me, and I'll make you seafood soup!",
  ui_story_5032_50320101_42_dialog_content = "Wow, Elvis' seafood soup!",
  ui_story_5032_50320101_43_dialog_content = "Awesome! It's a deal, then!",
  ui_story_5032_50320101_44_dialog_content = "Deal!",
  ui_story_5032_50320101_45_dialog_content = "We had a deal...",
  ui_story_5032_50320101_46_dialog_content = "We had agreed to meet...",
  ui_story_5032_50320101_47_dialog_content = "So how could you leave without saying goodbye?",
  ui_story_5032_50320101_48_dialog_content = "Why did you betray me? Why did you destroy my home? Why did you break my oath to True Order?",
  ui_story_5032_50320101_49_dialog_content = "And why do you look... so painful?",
  ui_story_5032_50320101_50_dialog_content = "Boss.",
  ui_story_5032_50320101_51_dialog_content = "Boss!",
  ui_story_5032_50320101_52_dialog_content = "Boss!!",
  ui_story_5032_50320101_53_dialog_content = "What?",
  ui_story_5032_50320101_54_dialog_content = "What were you looking at? You were miles away.",
  ui_story_5032_50320101_55_dialog_content = "Nothing. I was just thinking about how to repair the Emerald.",
  ui_story_5032_50320101_56_dialog_content = "Oh, really? I thought you'd given that task to Ciel and me.",
  ui_story_5032_50320101_57_dialog_content = "...",
  ui_story_5032_50320101_58_dialog_content = "Hey, boss.",
  ui_story_5032_50320101_59_dialog_content = "I don't really know what happened between you and Laird Elvis.",
  ui_story_5032_50320101_60_dialog_content = "But I heard the Caelestite say that Elvis asked to see you many times after he was detained.",
  ui_story_5032_50320101_61_dialog_content = "Hmph.",
  ui_story_5032_50320101_62_dialog_content = "I have nothing to say to someone who almost destroyed the Emerald.",
  ui_story_5032_50320101_63_dialog_content = "Oh... Is that so?",
  ui_story_5032_50320101_64_dialog_content = "But I do kinda feel bad for him. I heard his Modali Syndrome is getting worse.",
  ui_story_5032_50320101_65_dialog_content = "And he's refusing to eat...",
  ui_story_5032_50320101_66_dialog_content = "If this carries on... I don't think he's gonna last long with that frail body of his.",
  ui_story_5032_50320101_67_dialog_content = "What did you say!?",
  ui_story_5032_50320101_68_dialog_content = "Eh? Boss?",
  ui_story_5032_50320101_69_dialog_content = "Now where are you going?",
  ui_story_5032_50320101_70_dialog_content = "I just remembered we've run out of balloons.",
  ui_story_5032_50320101_71_dialog_content = "I'm going to buy some.",
  ui_story_5032_50320101_72_dialog_content = "Eh? What?",
  ui_story_5032_50320101_73_dialog_content = "There's a whole crate of them right where you were standing...",
  ui_story_5032_50320101_74_dialog_content = "Judge Matthieu, Assistant Judge Loewe.",
  ui_story_5032_50320101_75_dialog_content = "Sorry to keep you waiting.",
  ui_story_5032_50320101_76_dialog_content = "I have no idea Elvis had so many tasks to attend to each day.",
  ui_story_5032_50320101_77_dialog_content = "And how is he?",
  ui_story_5032_50320101_78_dialog_content = "The same. He refuses to eat or even drink.",
  ui_story_5032_50320101_79_dialog_content = "Really? I must admire his willpower.",
  ui_story_5032_50320101_80_dialog_content = "Er, may I ask, Your Highness, how long do you plan to continue this?",
  ui_story_5032_50320101_81_dialog_content = "We have, as you instructed, made the report to the Elder Council. But that will not satisfy them for long.",
  ui_story_5032_50320101_82_dialog_content = "We must find out Elvis' true motives soon and root out the seeds of rebellion.",
  ui_story_5032_50320101_83_dialog_content = "Otherwise the mess in Harbor City may end up becoming our problem to fix.",
  ui_story_5032_50320101_84_dialog_content = "Lord Schwartz is enraged, and the commoners have lost their beloved laird. Everyone is restless.",
  ui_story_5032_50320101_85_dialog_content = "It would be preferable to return to Lumopolis at once. And let Lord Schwartz send his men to investigate.",
  ui_story_5032_50320101_86_dialog_content = "No. First, I won't give up halfway.",
  ui_story_5032_50320101_87_dialog_content = "Second, I cannot just leave like that.",
  ui_story_5032_50320101_88_dialog_content = "If I do so, how can I be sure that Lord Schwartz and the citizens of Harbor City will get the answers they deserve?",
  ui_story_5032_50320101_89_dialog_content = "All right, all right. I understand. Forget what I said.",
  ui_story_5032_50320101_90_dialog_content = "But nevertheless, I thank you, Judge Matthieu.",
  ui_story_5032_50320101_91_dialog_content = "That's new.",
  ui_story_5032_50320101_92_dialog_content = "Huh? What's that? I can say useful things once in a while, alright?",
  ui_story_5032_50320101_93_dialog_content = "Sure.",
  ui_story_5032_50320101_94_dialog_content = "Wait until I finish writing my report, and I will teach you why I am the judge, and you are my assistant!",
  ui_story_5032_50320101_95_dialog_content = "Then, I shall leave the task of guarding Elvis in your capable hands.",
  ui_story_5032_50320101_96_dialog_content = "As you command.",
  ui_story_5032_50320101_97_dialog_content = "Carleen, we're back.",
  ui_story_5032_50320101_98_dialog_content = "How are you feeling? Does it still hurt?",
  ui_story_5032_50320101_99_dialog_content = "Welcome back. My wounds and my Lumina have both recovered quicker than I anticipated.",
  ui_story_5032_50320101_100_dialog_content = "I'm already well enough to handle any ordinary fight. Don't worry about me.",
  ui_story_5032_50320101_101_dialog_content = "How about those people protesting Elvis' detention? Have they left?",
  ui_story_5032_50320101_102_dialog_content = "Are you sure it's going to work?",
  ui_story_5032_50320101_103_dialog_content = "The majority of the protesters were willing to leave quietly once they heard Princess Carleen of Lumopolis was leading the investigation.",
  ui_story_5032_50320101_104_dialog_content = "But there are some holdouts who would not listen.",
  ui_story_5032_50320101_105_dialog_content = "Your wounds seemed serious after the battle, Carleen. You gave me quite the scare.",
  ui_story_5032_50320101_106_dialog_content = "Please, do not push yourself so hard in the future.",
  ui_story_5032_50320101_107_dialog_content = "I know. Sorry for worrying you guys, Vice, and PlayerName.",
  ui_story_5032_50320101_108_dialog_content = "Oh, and we ran into a guard on the way back who told us of scattered Eclipsites sighting on the beach.",
  ui_story_5032_50320101_109_dialog_content = "Eclipsites again? There have been reports of appearances lately.",
  ui_story_5032_50320101_110_dialog_content = "But our follow-up investigations came to nothing.",
  ui_story_5032_50320101_111_dialog_content = "Perhaps Patou will know something. He's the expert on the city's defenses.",
  ui_story_5032_50320101_112_dialog_content = "Hmm. Patou and the rest of Elvis' guards have been locked up alongside, but they are not cooperating.",
  ui_story_5032_50320101_113_dialog_content = "Elvis has been warning of an imminent crisis. Do you think that had something to do with the Eclipsites?",
  ui_story_5032_50320101_114_dialog_content = "Possibly. But as things stand, their numbers aren't high enough to represent a threat.",
  ui_story_5032_50320101_115_dialog_content = "And he refuses to say what the crisis will be. All he does is demand to see Jeno.",
  ui_story_5032_50320101_116_dialog_content = "His childhood friend? Well, that is touching...",
  ui_story_5032_50320101_117_dialog_content = "PlayerName, could you and Vice go to visit Elvis once more? See if you can find any clues in whatever he says.",
  ui_story_5032_50320101_118_dialog_content = "And talk to Jeno too. If he would be willing to speak to Elvis... Well, perhaps we could learn something more.",
  ui_story_5032_50320101_119_dialog_content = "Of course. Leave it with us.",
  ui_story_5032_50320201_1_dialog_content = "Rainbow, do you want to try restarting the system?",
  ui_story_5032_50320201_2_dialog_content = "Roger. I'll give it another shot.",
  ui_story_5032_50320201_3_dialog_content = "<color=#e8d9bb>... System restarting. Initiating self-testing.</color>",
  ui_story_5032_50320201_4_dialog_content = "<color=#e8d9bb>Anomalies detected.</color>",
  ui_story_5032_50320201_5_dialog_content = "<color=#e8d9bb>Engine system error.</color>",
  ui_story_5032_50320201_6_dialog_content = "<color=#e8d9bb>Transmission system error.</color>",
  ui_story_5032_50320201_7_dialog_content = "No good. It still won't start up.",
  ui_story_5032_50320201_8_dialog_content = "Sorry...",
  ui_story_5032_50320201_9_dialog_content = "Stop apologizing!",
  ui_story_5032_50320201_10_dialog_content = "I know you're trying your best. You've been helping me fix the engine system for ages and I can't remember the last time you had a break.",
  ui_story_5032_50320201_11_dialog_content = "It's okay.",
  ui_story_5032_50320201_12_dialog_content = "You helped me upgrade Styx. So now I need to help you get your Emerald up and running again.",
  ui_story_5032_50320201_13_dialog_content = "Because that's what friends are for, right?",
  ui_story_5032_50320201_14_dialog_content = "Yes! And you're a very good friend, Ciel.",
  ui_story_5032_50320201_15_dialog_content = "I'm so grateful to have you here helping me fix the Emerald.",
  ui_story_5032_50320201_16_dialog_content = "Hey, you're standing too close and I can't read the data.",
  ui_story_5032_50320201_17_dialog_content = "Hang on. Looking at these logs I've just extracted... has any machinery been removed from this ship?",
  ui_story_5032_50320201_18_dialog_content = "Could be. I remember the old engineer telling me the ship has a long and complex history.",
  ui_story_5032_50320201_19_dialog_content = "Unfortunately, he's not with us any longer. If he was—",
  ui_story_5032_50320201_20_dialog_content = "*Sobbing* If only he was still here—",
  ui_story_5032_50320201_21_dialog_content = "What happened? Did something bad happen to him?",
  ui_story_5032_50320201_22_dialog_content = "Nope. He said that he finally found a successor. And then just left when we docked without a goodbye.",
  ui_story_5032_50320201_23_dialog_content = "I heard he's married with kids now, and running a barbecue joint.",
  ui_story_5032_50320201_24_dialog_content = "But I still hadn't learned much from him. So I had to study it all myself. Luckily I enjoy it.",
  ui_story_5032_50320201_25_dialog_content = "And fortunately, the core doesn't require much maintenance and hasn't had a problem since I took over.",
  ui_story_5032_50320201_26_dialog_content = "That's actually incredibly reliable. It makes me wonder what the ship was used for originally...",
  ui_story_5032_50320201_27_dialog_content = "And with the Guardian, it just adds to the mystery.",
  ui_story_5032_50320201_28_dialog_content = "Actually, I did once ask my predecessor what that Guardian was.",
  ui_story_5032_50320201_29_dialog_content = "But he just brushed me off, saying it was probably just some decoration that looks cool.",
  ui_story_5032_50320201_30_dialog_content = "Hah. It sounds like he was a weird one.",
  ui_story_5032_50320201_31_dialog_content = "I know, right? But the Emerald is still working, even if it doesn't have the best engineers. It's a great ship!",
  ui_story_5032_50320201_32_dialog_content = "... Graagh!",
  ui_story_5032_50320201_33_dialog_content = "Wait. Did you hear something in the distance?",
  ui_story_5032_50320201_34_dialog_content = "Eh? Merylt, you really wrote PlayerName a letter?",
  ui_story_5032_50320201_35_dialog_content = "Let me help you! I can give it to him for you.",
  ui_story_5032_50320201_36_dialog_content = "You know, in case you are too shy to hand it over.",
  ui_story_5032_50320201_37_dialog_content = "But... I think I should give it to him personally.",
  ui_story_5032_50320201_38_dialog_content = "No, no! You must let me do it, Merylt!",
  ui_story_5032_50320201_39_dialog_content = "Subli's definitely gonna open it and read it! Her curiosity forbids her from doing otherwise.",
  ui_story_5032_50320201_40_dialog_content = "She might even add a few things to it.",
  ui_story_5032_50320201_41_dialog_content = "Eh? She wouldn't, would she?",
  ui_story_5032_50320201_42_dialog_content = "I'm sorry, Merylt, but Frimet knows me too well.",
  ui_story_5032_50320201_43_dialog_content = "Ah, give me back the letter!",
  ui_story_5032_50320201_44_dialog_content = "Bica, take it for me.",
  ui_story_5032_50320201_45_dialog_content = "Hai?",
  ui_story_5032_50320201_46_dialog_content = "Stop right there!",
  ui_story_5032_50320201_47_dialog_content = "Here's your letter.",
  ui_story_5032_50320201_48_dialog_content = "Th-thank you, Miss Fia.",
  ui_story_5032_50320201_49_dialog_content = "What a bunch of rowdy kids.",
  ui_story_5032_50320201_50_dialog_content = "Can't you be more mature? Like me.",
  ui_story_5032_50320201_51_dialog_content = "Oh, you're mature? I hadn't noticed.",
  ui_story_5032_50320201_52_dialog_content = "And if we're talking about strength, even Merylt could probably beat you.",
  ui_story_5032_50320201_53_dialog_content = "What did you say!? Wanna find out how strong I am?",
  ui_story_5032_50320201_54_dialog_content = "Subli, Frimet, stop teasing Miss Fia. She's a guest of the circus, remember?",
  ui_story_5032_50320201_55_dialog_content = "Fine, fine.",
  ui_story_5032_50320201_56_dialog_content = "Hmph. Hey, how come you three aren't staying on the land like the rest of the crew?",
  ui_story_5032_50320201_57_dialog_content = "I can look after the wondrous beasts myself.",
  ui_story_5032_50320201_58_dialog_content = "I'm a temporary member of the circus, after all, and taking care of animals is kind of my area of expertise.",
  ui_story_5032_50320201_59_dialog_content = "How could we?",
  ui_story_5032_50320201_60_dialog_content = "People in the city think it was us circus folk that harmed their beloved Laird Elvis.",
  ui_story_5032_50320201_61_dialog_content = "They'll give us the cold shoulder at best and might even try to start a fight.",
  ui_story_5032_50320201_62_dialog_content = "Besides, we prefer being on the Emerald anyway.",
  ui_story_5032_50320201_63_dialog_content = "After all, this is our home, you know?",
  ui_story_5032_50320201_64_dialog_content = "Yeah...",
  ui_story_5032_50320201_65_dialog_content = "I think I can understand how you feel.",
  ui_story_5032_50320201_66_dialog_content = "My work as an extrozoologist involves roaming around every corner of the continent—but sometimes, I still miss my mother's meat stew.",
  ui_story_5032_50320201_67_dialog_content = "And speaking of wondrous beasts, I still haven't achieved the goal that brought me to Harbor City.",
  ui_story_5032_50320201_68_dialog_content = "What's that?",
  ui_story_5032_50320201_69_dialog_content = "Come on, tell us. We might be able to help.",
  ui_story_5032_50320201_70_dialog_content = "Well, I guess there's no point being secretive now.",
  ui_story_5032_50320201_71_dialog_content = "Alright.",
  ui_story_5032_50320201_72_dialog_content = "I'm actually in search of an exotic wondrous beast. The <color=#FFB400>Cloudwhale</color>!",
  ui_story_5032_50320201_73_dialog_content = "What's that, some kind of whale?",
  ui_story_5032_50320201_74_dialog_content = "Y-Yeah, I guess so.",
  ui_story_5032_50320201_75_dialog_content = "I mean, it's not that I don't know. It's just that my lousy master didn't explain properly.",
  ui_story_5032_50320201_76_dialog_content = "He told me the Cloudwhale's energy trail disappeared somewhere in the ocean near here, then sent me to investigate.",
  ui_story_5032_50320201_77_dialog_content = "All I know is that its powerful Lumina can make the Eclipsites cower in fear and dispel even the thickest Darkflow.",
  ui_story_5032_50320201_78_dialog_content = "Whales? I've never seen one, but I've heard older circus folks talk about them.",
  ui_story_5032_50320201_79_dialog_content = "They're all huge and spend most of their time deep in the ocean.",
  ui_story_5032_50320201_80_dialog_content = "They seem like they'll easily get stranded if they come to shallow waters.",
  ui_story_5032_50320201_81_dialog_content = "Yeah, and aren't fish all scared of ships? I wouldn't expect one to swim anywhere near here.",
  ui_story_5032_50320201_82_dialog_content = "Argh! Has that man sent me on a wild goose chase?",
  ui_story_5032_50320201_83_dialog_content = "Then I'm having a crisis!",
  ui_story_5032_50320201_84_dialog_content = "Ah!",
  ui_story_5032_50320201_85_dialog_content = "Oops, sorry for suddenly shouting like that. Did I scare you?",
  ui_story_5032_50320201_86_dialog_content = "It-it's fine. I just dropped all my things, that's all.",
  ui_story_5032_50320201_87_dialog_content = "Don't move, I'll pick them up for you.",
  ui_story_5032_50320201_88_dialog_content = "Hah!",
  ui_story_5032_50320201_89_dialog_content = "Hah!!",
  ui_story_5032_50320201_90_dialog_content = "Is that everything? And what's this? Some kind of tasty snack?",
  ui_story_5032_50320201_91_dialog_content = "That's right, just like all those tasty candies you took last time! And it'll help you get taller.",
  ui_story_5032_50320201_92_dialog_content = "Subli, don't try and make Fia eat the fish food.",
  ui_story_5032_50320201_93_dialog_content = "Actually, that is the fish food I made myself.",
  ui_story_5032_50320201_94_dialog_content = "But if you liked that candy we had last time... I can make some for you!",
  ui_story_5032_50320201_95_dialog_content = "What, me? Nah, I'm too old for things like candy. I was just curious!",
  ui_story_5032_50320201_96_dialog_content = "Hey, Merylt, do you keep fish? Let me help you identify what breeds they are!",
  ui_story_5032_50320201_97_dialog_content = "It's that small one, over there.",
  ui_story_5032_50320201_98_dialog_content = "Hmm. Just this little gray fella. I can't tell what breed it is.",
  ui_story_5032_50320201_99_dialog_content = "Eep!",
  ui_story_5032_50320201_100_dialog_content = "Can it really eat all that in one meal? That's incredible!",
  ui_story_5032_50320201_101_dialog_content = "Our ringmaster found this little guy on the beach...",
  ui_story_5032_50320201_102_dialog_content = "He said it seemed injured and brought it back to me to look after it.",
  ui_story_5032_50320201_103_dialog_content = "Oh, and he said it was already in this bottle when he found it.",
  ui_story_5032_50320201_104_dialog_content = "I've ordered a proper fish tank, but it's not ready yet. So our little guy is stuck in there for now.",
  ui_story_5032_50320201_105_dialog_content = "I never thought that fierce ringmaster would be so kind to animals.",
  ui_story_5032_50320201_106_dialog_content = "Yeah... He even gave it a name: <color=#FFB400>Geedo</color>.",
  ui_story_5032_50320201_107_dialog_content = "Hey, Fia... Could this be the Cloudwhale you're looking for?",
  ui_story_5032_50320201_108_dialog_content = "Eep!",
  ui_story_5032_50320201_109_dialog_content = "Geedo's too tiny to be a Cloudwhale.",
  ui_story_5032_50320201_110_dialog_content = "Ringmaster Jeno told me that even a baby whale would be too big for this ship.",
  ui_story_5032_50320201_111_dialog_content = "And whales don't go \"eep eep.\" They go \"croak croak.\"",
  ui_story_5032_50320201_112_dialog_content = "Really? Isn't it \"hoot hoot.\"",
  ui_story_5032_50320201_113_dialog_content = "Totally wrong. It's \"woo woo.\"",
  ui_story_5032_50320201_114_dialog_content = "Isn't it \"chirp chirp\"?",
  ui_story_5032_50320201_115_dialog_content = "Graagh—",
  ui_story_5032_50320201_116_dialog_content = "You're all wrong! That's not what whales sound like. It's totally...",
  ui_story_5032_50320201_117_dialog_content = "Graagh—",
  ui_story_5032_50320201_118_dialog_content = "Eclipsites! How did Eclipsites get on board!?",
  ui_story_5032_50320202_1_dialog_content = "Ha—!",
  ui_story_5032_50320202_2_dialog_content = "Hey!",
  ui_story_5032_50320202_3_dialog_content = "There are more of them!",
  ui_story_5032_50320202_4_dialog_content = "Graagh...",
  ui_story_5032_50320202_5_dialog_content = "Watch out, Fia!",
  ui_story_5032_50320202_6_dialog_content = "Lousy Eclipsites! Take this!",
  ui_story_5032_50320202_7_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5032_50320202_8_dialog_content = "Graagh—",
  ui_story_5032_50320202_9_dialog_content = "Wow, I never expected you to be such a good fighter, Fia.",
  ui_story_5032_50320202_10_dialog_content = "Heehee. These weak Eclipsites are no match for me.",
  ui_story_5032_50320202_11_dialog_content = "They were obviously very weak.",
  ui_story_5032_50320202_12_dialog_content = "Guys! Are you all okay?",
  ui_story_5032_50320202_13_dialog_content = "Huff, huff... C-Ciel, you can't just rush in like that.",
  ui_story_5032_50320202_14_dialog_content = "It's too dangerous now you don't have Styx with you.",
  ui_story_5032_50320202_15_dialog_content = "I'm sorry. But I knew you were right behind me, Rainbow.",
  ui_story_5032_50320202_16_dialog_content = "Well, that's true.",
  ui_story_5032_50320202_17_dialog_content = "But it's still too dangerous. Don't do it again.",
  ui_story_5032_50320202_18_dialog_content = "Okay, I understand.",
  ui_story_5032_50320202_19_dialog_content = "Alright, nobody's hurt. That's the important thing.",
  ui_story_5032_50320202_20_dialog_content = "But where did these Eclipsites come from?",
  ui_story_5032_50320202_21_dialog_content = "No idea.",
  ui_story_5032_50320202_22_dialog_content = "Normally, we'd be able to check the Emerald's system logs and find out.",
  ui_story_5032_50320202_23_dialog_content = "But the system's still down, so I'm afraid we'll have to carry out a search place by place.",
  ui_story_5032_50320202_24_dialog_content = "I guess that's our only option.",
  ui_story_5032_50320202_25_dialog_content = "But a group of six is too big to go charging about in the ship.",
  ui_story_5032_50320202_26_dialog_content = "And too small a group could be dangerous if more Eclipsites turn up.",
  ui_story_5032_50320202_27_dialog_content = "So let's split up into two teams.",
  ui_story_5032_50320202_28_dialog_content = "Merylt, you and your sisters are strong fighters. You three can be one team.",
  ui_story_5032_50320202_29_dialog_content = "Roger that!",
  ui_story_5032_50320202_30_dialog_content = "We're not very familiar with the stuff inside the ship, so we should go up to check the deck and its surroundings.",
  ui_story_5032_50320202_31_dialog_content = "Okay, we'll leave that to you.",
  ui_story_5032_50320202_32_dialog_content = "Then I will follow Rainbow and Ciel to check the inside of the ship.",
  ui_story_5032_50320202_33_dialog_content = "Okay. But don't wander around and touch random stuff just because you're curious.",
  ui_story_5032_50320202_34_dialog_content = "There could still be Eclipsites hanging around.",
  ui_story_5032_50320202_35_dialog_content = "Okay, I won't.",
  ui_story_5032_50320301_1_dialog_content = "Elvis still won't talk.",
  ui_story_5032_50320301_2_dialog_content = "He keeps on muttering about wanting to see Jeno. So I guess we need to talk to Jeno.",
  ui_story_5032_50320301_3_dialog_content = "But last time I tried, he shut himself in his cabin and refused to come out.",
  ui_story_5032_50320301_4_dialog_content = "What happened with Elvis affected him very badly. It seems they were close friends in the past.",
  ui_story_5032_50320301_5_dialog_content = "Yeah. So if we can persuade him to help, maybe he can get Elvis to talk.",
  ui_story_5032_50320301_6_dialog_content = "...",
  ui_story_5032_50320301_7_dialog_content = "Hey, that guy walking around looking lost... could that be Jeno?",
  ui_story_5032_50320301_8_dialog_content = "Hey! Jeno!",
  ui_story_5032_50320301_9_dialog_content = "Oh, it's you guys.",
  ui_story_5032_50320301_10_dialog_content = "It is you, Jeno.",
  ui_story_5032_50320301_11_dialog_content = "I came to see you earlier, but... you wouldn't come out.",
  ui_story_5032_50320301_12_dialog_content = "Sorry. I wasn't in a good mood.",
  ui_story_5032_50320301_13_dialog_content = "It's okay. But where are you going? You seem lost.",
  ui_story_5032_50320301_14_dialog_content = "To tell the truth...",
  ui_story_5032_50320301_15_dialog_content = "I want to speak to Elvis.",
  ui_story_5032_50320301_16_dialog_content = "Is this where they're keeping him?",
  ui_story_5032_50320301_17_dialog_content = "It's not what I expected.",
  ui_story_5032_50320301_18_dialog_content = "\"He was noble and a laird. We have to treat him with dignity, at least until he's found guilty.\"",
  ui_story_5032_50320301_19_dialog_content = "That's what Carleen said. So we let him stay here.",
  ui_story_5032_50320301_20_dialog_content = "He's guarded by Matthieu and Loewe from the Hall of Justice and some guards.",
  ui_story_5032_50320301_21_dialog_content = "Judge Matthieu, this is the man Elvis has been asking to see.",
  ui_story_5032_50320301_22_dialog_content = "Tsk, this is the commoner? He's been going on and on about you. Jeno this, Jeno that. I'm sick of hearing it.",
  ui_story_5032_50320301_23_dialog_content = "...",
  ui_story_5032_50320301_24_dialog_content = "I'll warn you now—no tricks. If you try anything, we'll attack without warning.",
  ui_story_5032_50320301_25_dialog_content = "Hmph.",
  ui_story_5032_50320301_26_dialog_content = "<color=#e8d9bb>Click</color>",
  ui_story_5032_50320301_27_dialog_content = "Jeno? Is that you, Jeno!?",
  ui_story_5032_50320301_28_dialog_content = "You've finally come to see me.",
  ui_story_5032_50320301_29_dialog_content = "Hmm.",
  ui_story_5032_50320301_30_dialog_content = "Don't misunderstand. I'm just here to see what happens to treacherous traitors.",
  ui_story_5032_50320301_31_dialog_content = "I hadn't expected to find you in such comfortable accommodation.",
  ui_story_5032_50320301_32_dialog_content = "It seems unfair when you think of all the damage you did to my Emerald.",
  ui_story_5032_50320301_33_dialog_content = "Do you know how hard everyone has to work to repair it?",
  ui_story_5032_50320301_34_dialog_content = "And you sit here, lounging in your clean and comfortable room.",
  ui_story_5032_50320301_35_dialog_content = "Jeno, I am truly sorry.",
  ui_story_5032_50320301_36_dialog_content = "Please believe me, and if I had any other choice, I wouldn't have hurt you.",
  ui_story_5032_50320301_37_dialog_content = "But you did. Didn't you?",
  ui_story_5032_50320301_38_dialog_content = "Facts are facts, and we can't change them. So what's the point of saying sorry?",
  ui_story_5032_50320301_39_dialog_content = "I heard you refused to eat and drink and insisted on seeing me.",
  ui_story_5032_50320301_40_dialog_content = "What do you expect? That I'll listen to your tedious apologies and forgive you for all you have done?",
  ui_story_5032_50320301_41_dialog_content = "Will telling me in person how much you regret it all ease your conscience a little?",
  ui_story_5032_50320301_42_dialog_content = "Jeno... I know how much I owe you.",
  ui_story_5032_50320301_43_dialog_content = "But there are some things I can tell only you.",
  ui_story_5032_50320301_44_dialog_content = "Things that will be significant only to you.",
  ui_story_5032_50320301_45_dialog_content = "I don't expect anything you say to be significant.",
  ui_story_5032_50320301_46_dialog_content = "Look at yourself, Elvis. You're pathetic.",
  ui_story_5032_50320301_47_dialog_content = "Yes. I know how far I have fallen.",
  ui_story_5032_50320301_48_dialog_content = "I must look like I did <color=#FFB400>that time I hurt my leg</color>, fighting those thugs.",
  ui_story_5032_50320301_49_dialog_content = "I remember how you mocked me.",
  ui_story_5032_50320301_50_dialog_content = "I didn't come here to reminisce.",
  ui_story_5032_50320301_51_dialog_content = "I'm sorry. I thought you once said you were a nostalgic person... I thought you might like to remember old times.",
  ui_story_5032_50320301_52_dialog_content = "After all, everyone has small secrets hidden away in their memories.",
  ui_story_5032_50320301_53_dialog_content = "I'm in no mood to remember the past. And I don't even remember you hurt your leg.",
  ui_story_5032_50320301_54_dialog_content = "No, you do. I'm sure you do.",
  ui_story_5032_50320301_55_dialog_content = "Just as you know the meaning of secrets.",
  ui_story_5032_50320301_56_dialog_content = "Nonsense!",
  ui_story_5032_50320301_57_dialog_content = "This is pointless. If this is all you have to say, save your breath. I'm not interested.",
  ui_story_5032_50320301_58_dialog_content = "Jeno!",
  ui_story_5032_50320301_59_dialog_content = "Jeno just stormed out like that?",
  ui_story_5032_50320301_60_dialog_content = "He seemed furious...",
  ui_story_5032_50320301_61_dialog_content = "I don't know the history between you two, but maybe you should try a more sincere apology.",
  ui_story_5032_50320301_62_dialog_content = "Anyway, will you eat something, now we've let you see Jeno?",
  ui_story_5032_50320301_63_dialog_content = "Hmm. Thank you for the advice, PlayerName.",
  ui_story_5032_50320301_64_dialog_content = "Elvis! Are you okay?",
  ui_story_5032_50320301_65_dialog_content = "Don't worry. It's just my leg. And they won't bully you like that again.",
  ui_story_5032_50320301_66_dialog_content = "I'm sorry... It's all my fault.",
  ui_story_5032_50320301_67_dialog_content = "I told you not to worry about it. So is this the secret base you found?",
  ui_story_5032_50320301_68_dialog_content = "Yeah. There's hardly anyone here and it's perfect for painting.",
  ui_story_5032_50320301_69_dialog_content = "Let's go in then! It could be a cool place to hide things too. Maybe I'll keep my diary here.",
  ui_story_5032_50320301_70_dialog_content = "Eh? I didn't know you had a diary.",
  ui_story_5032_50320301_71_dialog_content = "Yeah, but maybe I'll start one.",
  ui_story_5032_50320301_72_dialog_content = "After all, a secret base is perfect for keeping secrets.",
  ui_story_5032_50320301_73_dialog_content = "<color=#e8d9bb>The outskirts of Harbor City</color>",
  ui_story_5032_50320301_74_dialog_content = "What have you left here that you want me to find so badly?",
  ui_story_5032_50320301_75_dialog_content = "Surely it can't be that stupid diary...",
  ui_story_5032_50320301_76_dialog_content = "Graagh—!",
  ui_story_5032_50320301_77_dialog_content = "I can't believe there are Eclipsites here.",
  ui_story_5032_50320301_78_dialog_content = "Graagh!!",
  ui_story_5032_50320301_79_dialog_content = "Get out of the way!",
  ui_story_5032_50320302_1_dialog_content = "Graagh—",
  ui_story_5032_50320302_2_dialog_content = "I think that was the last one.",
  ui_story_5032_50320302_3_dialog_content = "The tree that Eclipsite hit was the same one Elvis rested against when he hurt his leg.",
  ui_story_5032_50320302_4_dialog_content = "It's grown so tall.",
  ui_story_5032_50320302_5_dialog_content = "There really is a letter. How cliche.",
  ui_story_5032_50320302_6_dialog_content = "And am I supposed to just read it?",
  ui_story_5032_50320302_7_dialog_content = "Secret plots should be a little more creative than this.",
  ui_story_5032_50320302_8_dialog_content = "I should just tear apart this ridiculous plan of yours...",
  ui_story_5032_50320302_9_dialog_content = "No, maybe I should read it. It might provide a good laugh.",
  ui_story_5032_50320302_10_dialog_content = "Since I have already decided not to forgive you, what's a letter gonna do to change that?",
  ui_story_5032_50320302_11_dialog_content = "Even now, Jeno, you still want to know what pathetic excuses he has, don't you?",
  ui_story_5032_50320302_12_dialog_content = "You are just as laughable as he is.",
  ui_story_5032_50320302_13_dialog_content = "Very well. I will see what else you have to say for yourself.",
  ui_story_5032_50320302_14_dialog_content = "To my dear friend Jeno",
  ui_story_5032_50320302_15_dialog_content = "By the time you read this, I may have freed the people of Harbor City from the curse they suffer.",
  ui_story_5032_50320302_16_dialog_content = "Or, if my plan has failed, I may have become a prisoner.",
  ui_story_5032_50320302_17_dialog_content = "But whichever is the case, I'm in dire need of your assistance.",
  ui_story_5032_50320302_18_dialog_content = "I beg of you, read this letter to its end.",
  ui_story_5032_50320302_19_dialog_content = "You probably already know that my target was the Emerald's energy core.",
  ui_story_5032_50320302_20_dialog_content = "I have asked myself time and again if I should reveal my plans to you. After all, there was a time when we had no secrets from each other.",
  ui_story_5032_50320302_21_dialog_content = "But after so many years apart, we may have both grown into very different people.",
  ui_story_5032_50320302_22_dialog_content = "And years of playing political games have made me wary of trusting others.",
  ui_story_5032_50320302_23_dialog_content = "Even when we met once again, I still couldn't bring myself to fully trust you.",
  ui_story_5032_50320302_24_dialog_content = "It was then that I saw it in your eyes—the Emerald is more than a mere ship to you.",
  ui_story_5032_50320302_25_dialog_content = "It has become a home. A home for you, for your family, and for your friends.",
  ui_story_5032_50320302_26_dialog_content = "And you have become a member of True Order.",
  ui_story_5032_50320302_27_dialog_content = "I cannot tell you the truth, or bear the consequences should other forces learn about the energy core.",
  ui_story_5032_50320302_28_dialog_content = "It is the last hope for Harbor City and those poor cursed souls who live here.",
  ui_story_5032_50320302_29_dialog_content = "The <color=#FFB400>Windstone</color>'s seal is weakening. If that continues, Harbor City is doomed to destruction.",
  ui_story_5032_50320302_30_dialog_content = "I need your help and I promise to explain everything in person. But I must complete the ritual as soon as you can.",
  ui_story_5032_50320302_31_dialog_content = "I hope you will lend a helping hand to this place, your former home. And me, your former friend.",
  ui_story_5032_50320302_32_dialog_content = "Was this what you wanted to say?",
  ui_story_5032_50320302_33_dialog_content = "You think you can fool me again with a mere letter?",
  ui_story_5032_50320302_34_dialog_content = "Do you think I will forgive you now?",
  ui_story_5032_50320302_35_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_5032_50320302_36_dialog_content = "You fool, Elvis.",
  ui_story_5032_50320401_1_dialog_content = "Carleen, we're back.",
  ui_story_5032_50320401_2_dialog_content = "Welcome back. How did it go?",
  ui_story_5032_50320401_3_dialog_content = "And where's Jeno? I thought he'd be with you.",
  ui_story_5032_50320401_4_dialog_content = "He fought with Elvis and then stormed off. We couldn't stop him.",
  ui_story_5032_50320401_5_dialog_content = "Figured as much. He must have a lot on his mind right now...",
  ui_story_5032_50320401_6_dialog_content = "After everything that's happened, he probably needs some time alone to think things through.",
  ui_story_5032_50320401_7_dialog_content = "We should give him that space.",
  ui_story_5032_50320401_8_dialog_content = "I still think Elvis is hiding something important from us.",
  ui_story_5032_50320401_9_dialog_content = "But we have no idea what's going on inside his head.",
  ui_story_5032_50320401_10_dialog_content = "Yeah...",
  ui_story_5032_50320401_11_dialog_content = "Carleen, do you have any ideas?",
  ui_story_5032_50320401_12_dialog_content = "The most important thing right now is to figure out what Elvis was up to, and why the Eclipsites have started appearing.",
  ui_story_5032_50320401_13_dialog_content = "Here's a guess. The increase in Eclipsites might be linked to that seal Elvis mentioned.",
  ui_story_5032_50320401_14_dialog_content = "Well, since he's not going to tell us anything, we'll have to find another way to get to the bottom of this.",
  ui_story_5032_50320401_15_dialog_content = "But where do we start?",
  ui_story_5032_50320401_16_dialog_content = "I remember something Elvis once said—",
  ui_story_5032_50320401_17_dialog_content = "You'll find the information you need too, once you've perused every book in this world.",
  ui_story_5032_50320401_18_dialog_content = "So what are we supposed to do? Read every book in Astra?",
  ui_story_5032_50320401_19_dialog_content = "No. Just all the books Elvis ever read.",
  ui_story_5032_50320401_20_dialog_content = "I remember there was a small library in his mansion. We should be able to find some leads there.",
  ui_story_5032_50320401_21_dialog_content = "I'll come and help. An extra pair of eyes will speed things up.",
  ui_story_5032_50320401_22_dialog_content = "Yeah, me too.",
  ui_story_5032_50320401_23_dialog_content = "<color=#e8d9bb>The library, Elvis' mansion</color>",
  ui_story_5032_50320401_24_dialog_content = "You... You call this a small library!?",
  ui_story_5032_50320401_25_dialog_content = "I mean, the room isn't very big...",
  ui_story_5032_50320401_26_dialog_content = "But it's packed full of bookcases. And the bookcases are packed full of books.",
  ui_story_5032_50320401_27_dialog_content = "It'll take us a year to read all of these. No, two years, minimum!",
  ui_story_5032_50320401_28_dialog_content = "And look, the books are all falling apart. Elvis must have read them all over and over.",
  ui_story_5032_50320401_29_dialog_content = "What was he hoping to learn from these?",
  ui_story_5032_50320401_30_option_content = "Maybe he was studying history?",
  ui_story_5032_50320401_31_dialog_content = "Elvis wanted to cure Modali Syndrome, so he was probably looking for clues about the Heroic Bloodline.",
  ui_story_5032_50320401_32_dialog_content = "The Heroic Bloodline has deep roots in Harbor City's history.",
  ui_story_5032_50320401_33_dialog_content = "If I wanted to learn about Modali Syndrome, I'd start with the history of Harbor City.",
  ui_story_5032_50320401_34_dialog_content = "That's true. It's a history full of unsolved mysteries.",
  ui_story_5032_50320401_35_dialog_content = "Perhaps one of those mysteries has something to do with Modali Syndrome?",
  ui_story_5032_50320401_36_option_content = "Maybe he was researching Modali Syndrome?",
  ui_story_5032_50320401_37_dialog_content = "He cared more about that than anything else, didn't he?",
  ui_story_5032_50320401_38_dialog_content = "The disease that he, as well as who knows how many citizens of Harbor City, suffers from.",
  ui_story_5032_50320401_39_dialog_content = "But scholars have been trying to figure out what causes it for ages and still got nowhere.",
  ui_story_5032_50320401_40_dialog_content = "Where would Elvis even start to look?",
  ui_story_5032_50320401_41_dialog_content = "Well, it's a local disease. So the best approach might be to look at local history.",
  ui_story_5032_50320401_42_dialog_content = "Then let's start with the history books.",
  ui_story_5032_50320401_43_dialog_content = "Okay. I'll gather up all the history books, and you guys can start reading them!",
  ui_story_5032_50320401_44_dialog_content = "Leave it to us!",
  ui_story_5032_50320401_45_dialog_content = "The Chronicles of Astra, The Encyclopedia of History, The Secret History of Lumopolis...",
  ui_story_5032_50320401_46_dialog_content = "Huh? And why is there a copy of The Legendary Heroes of Harbor City on the history shelf?",
  ui_story_5032_50320401_47_dialog_content = "Isn't this more of a mythology book? Whatever, I'll bring it along.",
  ui_story_5032_50320401_48_dialog_content = "Vice, Carleen, here are the books.",
  ui_story_5032_50320401_49_dialog_content = "Okay, put them here and we'll start reading.",
  ui_story_5032_50320401_50_dialog_content = "Thanks, PlayerName.",
  ui_story_5032_50320401_51_dialog_content = "No problem. I think there are some more history books over there. I'll go and check.",
  ui_story_5032_50320401_52_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_5032_50320401_53_dialog_content = "Phew. Okay, these are all the books with the word \"history\" in the title and anything that looks... y'know, historical.",
  ui_story_5032_50320401_54_dialog_content = "How is it going? Found anything yet?",
  ui_story_5032_50320401_55_dialog_content = "There's something strange about these books. The ones about Harbor City are all in agreement on its early history.",
  ui_story_5032_50320401_56_dialog_content = "But as soon as we read the more recent bits, they all diverge.",
  ui_story_5032_50320401_57_dialog_content = "And it doesn't even read like history. It's more like made-up stories.",
  ui_story_5032_50320401_58_dialog_content = "Yeah. Like this one, The Chronicles of Astra, says this:",
  ui_story_5032_50320401_59_dialog_content = "\"There was once a bloody battle between the ancient heroes and the Eclipsites near Harbor City.\"",
  ui_story_5032_50320401_60_dialog_content = "\"The hateful spirits of the Eclipsites became a curse which tormented the descendants of the heroes.\"",
  ui_story_5032_50320401_61_dialog_content = "Isn't that the legend we heard initially?",
  ui_story_5032_50320401_62_dialog_content = "But it's just a legend, right? If curses really exist, the whole world would descend into chaos...",
  ui_story_5032_50320401_63_dialog_content = "That one at least sounds half-believable. This one, The Legendary Heroes of Harbor City, is even weirder.",
  ui_story_5032_50320401_64_dialog_content = "\"Harbor City is protected by the heroes of old and so goes unmolested by the Eclipsites.\"",
  ui_story_5032_50320401_65_dialog_content = "\"Although Eclipsites may approach the city, they are soon quietly disposed of by the heroes.\"",
  ui_story_5032_50320401_66_dialog_content = "That's bizarre!",
  ui_story_5032_50320401_67_dialog_content = "I know, right!?",
  ui_story_5032_50320401_68_dialog_content = "Eh? This book says...",
  ui_story_5032_50320401_69_dialog_content = "Vice, what have you got?",
  ui_story_5032_50320401_70_dialog_content = "It's The Secret History of Lumopolis. It says the residents of Harbor City once excavated a site of ancient ruins.",
  ui_story_5032_50320401_71_dialog_content = "And in ruins, they found a strange stone. And if the stone was infused with Lumina, it could <color=#FFB400>repel nearby Eclipsites</color>.",
  ui_story_5032_50320401_72_dialog_content = "That sounds familiar. It'd be like a miniature version of Lumopolis' barrier.",
  ui_story_5032_50320401_73_dialog_content = "Don't interrupt, PlayerName. I haven't finished.",
  ui_story_5032_50320401_74_dialog_content = "Oh, sorry. What happened next?",
  ui_story_5032_50320401_75_dialog_content = "Here's what it says—",
  ui_story_5032_50320401_76_dialog_content = "\"But as the stone required <color=#FFB400>too much Lumina</color> to function, no source could keep it running constantly.\"",
  ui_story_5032_50320401_77_dialog_content = "\"And so it came to be regarded as worthless and was later lost.\"",
  ui_story_5032_50320401_78_dialog_content = "It sounds like a pointless legend. Keep looking.",
  ui_story_5032_50320401_79_dialog_content = "Although... The power that repels Eclipsites? That reminds me of something I read about in a book back in Lumopolis.",
  ui_story_5032_50320401_80_dialog_content = "At some point in the past, a horde of Eclipsites gathered in the Harbor City area. The residents fought and suffered from them for years.",
  ui_story_5032_50320401_81_dialog_content = "Then one day, the Eclipsites suddenly just disappeared and the city was free to prosper.",
  ui_story_5032_50320401_82_dialog_content = "So what made them disappear?",
  ui_story_5032_50320401_83_dialog_content = "No idea. I guess it's just one of those unsolved Harbor City mysteries.",
  ui_story_5032_50320401_84_dialog_content = "Ow, my neck. I've been reading so long, it's gone stiff.",
  ui_story_5032_50320401_85_dialog_content = "Take a break. I'll read the rest for you.",
  ui_story_5032_50320401_86_dialog_content = "Oh, thanks, PlayerName.",
  ui_story_5032_50320401_87_dialog_content = "I'll take a nap against this book cas—woah!!",
  ui_story_5032_50320401_88_dialog_content = "What's wrong? Did you bump into something?",
  ui_story_5032_50320401_89_dialog_content = "N-no. I just accidentally pushed one of these books.",
  ui_story_5032_50320401_90_dialog_content = "Is it an earthquake?",
  ui_story_5032_50320401_91_dialog_content = "No, it's not.",
  ui_story_5032_50320401_92_dialog_content = "Look, it's that wall over there. It's moving!",
  ui_story_5032_50320401_93_dialog_content = "And look, there's something behind the wall. It's...",
  ui_story_5032_50320401_94_dialog_content = "A table, piled with handwritten documents?",
  ui_story_5032_50320401_95_dialog_content = "If Elvis hid these away so carefully, they must be important.",
  ui_story_5032_50320401_96_dialog_content = "And we'd never have found the secret room if it wasn't for Vice's good luck.",
  ui_story_5032_50320401_97_dialog_content = "Let's see what these documents say.",
  ui_story_5032_50320401_98_dialog_content = "The pages on top have been yellowed. They must be older.",
  ui_story_5032_50320401_99_dialog_content = "I hereby start my research on the Windstone. Not only for myself but for the future of the citizens of Harbor City.",
  ui_story_5032_50320401_100_dialog_content = "It's Elvis's handwriting. He really was doing secret research. But what's the Windstone?",
  ui_story_5032_50320401_101_dialog_content = "I don't know. But if he's studying it, there should be more information later on!",
  ui_story_5032_50320401_102_dialog_content = "My research has found that the Windstone contains a device that can store energy.",
  ui_story_5032_50320401_103_dialog_content = "Its energy reserve and the intermittent supplies of Lumina from the Aurorians have managed to keep it operating to date.",
  ui_story_5032_50320401_104_dialog_content = "But it is consuming more energy than that can be supplied, and its energy reserve is almost exhausted.",
  ui_story_5032_50320401_105_dialog_content = "I can feel the Windstone's power weakening, and we are starting to see Eclipsites appear near Harbor City.",
  ui_story_5032_50320401_106_dialog_content = "If this continues, it will not be long before the city is once again plagued by Eclipsites.",
  ui_story_5032_50320401_107_dialog_content = "Time is ticking away. I must think of something.",
  ui_story_5032_50320401_108_dialog_content = "So it sounds like the Windstone is some kind of apparatus with special powers.",
  ui_story_5032_50320401_109_dialog_content = "So could this be why Harbor City was safe from the Eclipsites for so long?",
  ui_story_5032_50320401_110_dialog_content = "What's described here certainly matches up with Harbor City's actual situation.",
  ui_story_5032_50320401_111_dialog_content = "In the past, no Eclipsites have ever set foot in Harbor City. But recently, there have been many reports of Eclipsites attacking Aurorians.",
  ui_story_5032_50320401_112_dialog_content = "Whether the weakening of the so-called Windstone is the cause, this phenomenon does not bode well.",
  ui_story_5032_50320401_113_dialog_content = "Let's keep reading. The papers below seem newer, so the writing should be more recent.",
  ui_story_5032_50320401_114_dialog_content = "I thumbed through all the history books I could find, looking for the Windstone's origin.",
  ui_story_5032_50320401_115_dialog_content = "My ancestors dug up Windstone in the ruins and discovered it has great power, sufficient to seal the Eclipsites.",
  ui_story_5032_50320401_116_dialog_content = "To protect the homeland, they made a blood pact with the Windstone and supplied the Lumina it needed to operate.",
  ui_story_5032_50320401_117_dialog_content = "And thus, the power of Windstone put the Eclipsites harassing Harbor City to deep slumber.",
  ui_story_5032_50320401_118_dialog_content = "But if the Windstone stops working, the Eclipsites will wake up and sack Harbor City again.",
  ui_story_5032_50320401_119_dialog_content = "The seal and blood pact... That sounds like the power mentioned in that book.",
  ui_story_5032_50320401_120_dialog_content = "Isn't it a baseless rumor?",
  ui_story_5032_50320401_121_dialog_content = "And supposedly, the Windstone needed massive Lumina to work, so they gave it up.",
  ui_story_5032_50320401_122_dialog_content = "Let's go ahead.",
  ui_story_5032_50320401_123_dialog_content = "The research finally made progress.",
  ui_story_5032_50320401_124_dialog_content = "Windstone is able to identify the contractors and their blood relatives, as well as to automatically absorb Lumina from such Aurorians.",
  ui_story_5032_50320401_125_dialog_content = "Now that the stone is nearly exhausted, it begins to absorb Lumina without restraint.",
  ui_story_5032_50320401_126_dialog_content = "But even if it could take everything from those Aurorians, it still won't have enough Lumina.",
  ui_story_5032_50320401_127_dialog_content = "When the supply finally runs out, every Aurorian born of that bloodline will die from the loss of Lumina.",
  ui_story_5032_50320401_128_dialog_content = "Uh... Don't tell me...",
  ui_story_5032_50320401_129_dialog_content = "That's probably the root of Modali Syndrome.",
  ui_story_5032_50320401_130_dialog_content = "Elvis... and his clan are using their Lumina and even lives to power the Windstone.",
  ui_story_5032_50320401_131_dialog_content = "But why? Is there no better way?",
  ui_story_5032_50320401_132_dialog_content = "Elvis never reported it to Lumopolis as the laird of Harbor City.",
  ui_story_5032_50320401_133_dialog_content = "Why would he do that?",
  ui_story_5032_50320401_134_dialog_content = "The Windstone is getting even weaker. Worse still, Lumopolis has launched a covert investigation of Harbor City.",
  ui_story_5032_50320401_135_dialog_content = "Windstone is probably just an interesting toy to Lumo nobles.",
  ui_story_5032_50320401_136_dialog_content = "The same goes for the scientists in Illumina. Once the presence of Windstone is known, they will certainly send people to seize it.",
  ui_story_5032_50320401_137_dialog_content = "To Harbor City, the stone is the foundation of its existence, the critical thing that prevents people from being displaced.",
  ui_story_5032_50320401_138_dialog_content = "I must keep it in an absolutely safe and unsuspected place so that outsiders won't learn of it.",
  ui_story_5032_50320401_139_dialog_content = "The good news is that there's a breakthrough in the study.",
  ui_story_5032_50320401_140_dialog_content = "After countless failures, I finally found a way for the stone to be powered by another source.",
  ui_story_5032_50320401_141_dialog_content = "All that's left now is to go to the sealed ground to restart it.",
  ui_story_5032_50320401_142_dialog_content = "That's the last passage, written in a rush.",
  ui_story_5032_50320401_143_dialog_content = "Somewhere absolutely safe... Can that strange rock on Elvis's scepter be the actual Windstone?",
  ui_story_5032_50320401_144_dialog_content = "Is Lumopolis that untrustworthy to you, Elvis?",
  ui_story_5032_50320401_145_dialog_content = "Carleen...",
  ui_story_5032_50320401_146_dialog_content = "Explain it to Elvis when you get the chance.",
  ui_story_5032_50320401_147_dialog_content = "Vice and I both could prove you are a trustworthy person!",
  ui_story_5032_50320401_148_dialog_content = "All right... Thanks.",
  ui_story_5032_50320401_149_dialog_content = "The manuscript ended with Elvis saying he found a way for the Windstone to use another power source.",
  ui_story_5032_50320401_150_dialog_content = "Windstone, Lumina, massive energy...",
  ui_story_5032_50320401_151_dialog_content = "I got it. He wanted the energy core on the circus ship to power the stone.",
  ui_story_5032_50320401_152_dialog_content = "That's why he sought the core even at the cost of breaking up with friends...",
  ui_story_5032_50320401_153_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5032_50320401_154_dialog_content = "Quick, over there!",
  ui_story_5032_50320401_155_dialog_content = "What's going on? Why all the noise?",
  ui_story_5032_50320401_156_dialog_content = "Stop that man! He broke out of prison!",
  ui_story_5032_50320401_157_dialog_content = "A prison break?!",
  ui_story_5032_50320401_158_dialog_content = "Don't tell me it's Elvis?!",
  ui_story_5032_50320401_159_dialog_content = "Come on, let's go check!",
  ui_story_5032_50320501_1_dialog_content = "Please keep your eyes on the suspect.",
  ui_story_5032_50320501_2_dialog_content = "I have to leave for half an hour.",
  ui_story_5032_50320501_3_dialog_content = "Going shower again?",
  ui_story_5032_50320501_4_dialog_content = "Harbor City is so humid and stuffy now.",
  ui_story_5032_50320501_5_dialog_content = "You'll be covered in sticky sweat after taking a shower, anyway.",
  ui_story_5032_50320501_6_dialog_content = "The fourth time? For today?",
  ui_story_5032_50320501_7_dialog_content = "I don't mind you taking one and adding it to my count.",
  ui_story_5032_50320501_8_dialog_content = "I'm an assistant judge.",
  ui_story_5032_50320501_9_dialog_content = "No, no. Technically, you're a rather stinky assistant judge.",
  ui_story_5032_50320501_10_dialog_content = "!!",
  ui_story_5032_50320501_11_dialog_content = "Huh? Are you flustered?",
  ui_story_5032_50320501_12_dialog_content = "Never mind. I'm getting a shower whether you like it or not.",
  ui_story_5032_50320501_13_dialog_content = "Keep your eyes glued to the laird.",
  ui_story_5032_50320501_14_dialog_content = "Yet that might be moot. He even has problems standing up without his scepter.",
  ui_story_5032_50320501_15_dialog_content = "Who knows if he could even make it to the court...",
  ui_story_5032_50320501_16_dialog_content = "...",
  ui_story_5032_50320501_17_dialog_content = "Will Jeno pick up the letter I left him?",
  ui_story_5032_50320501_18_dialog_content = "Or not at all, or perhaps still won't forgive me after reading it.",
  ui_story_5032_50320501_19_dialog_content = "I know I keep betraying your trust, so I shouldn't hold out any hope.",
  ui_story_5032_50320501_20_dialog_content = "I'm sorry, Jeno... But you're the only one that can help the people of Harbor City and me.",
  ui_story_5032_50320501_21_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5032_50320501_22_dialog_content = "You done mumbling?",
  ui_story_5032_50320501_23_dialog_content = "If so, come with me.",
  ui_story_5032_50320501_24_dialog_content = "Jeno!",
  ui_story_5032_50320501_25_dialog_content = "Don't get too excited there.",
  ui_story_5032_50320501_26_dialog_content = "You have to tell me everything, plus what you plan to do next.",
  ui_story_5032_50320501_27_dialog_content = "Or I'll toss you back here myself.",
  ui_story_5032_50320501_28_dialog_content = "...",
  ui_story_5032_50320501_29_dialog_content = "Why do the guards not attack or raise alarms?",
  ui_story_5032_50320501_30_dialog_content = "They aren't even looking at us, like nothing's happening.",
  ui_story_5032_50320501_31_dialog_content = "Such is the power of the Origin Deck. It makes them hallucinate.",
  ui_story_5032_50320501_32_dialog_content = "But the guards are nevertheless too complacent, and that gave me the opening.",
  ui_story_5032_50320501_33_dialog_content = "Only the judge from Lumopolis made me work a bit.",
  ui_story_5032_50320501_34_dialog_content = "I guess they didn't expect anyone to break you out.",
  ui_story_5032_50320501_35_dialog_content = "Haha, too bad they were wrong.",
  ui_story_5032_50320501_36_dialog_content = "Hallucination, you said. So what other interesting things can you do with the \"Origin\" power?",
  ui_story_5032_50320501_37_dialog_content = "Stop buttering me up. I still want an explanation from you.",
  ui_story_5032_50320501_38_dialog_content = "I'm not even sure I'll forgive you yet.",
  ui_story_5032_50320501_39_dialog_content = "But from what Lady Victoria said...",
  ui_story_5032_50320501_40_dialog_content = "The Origin Deck is multipurpose when it comes to <color=#FFB400>energy conversion</color>.",
  ui_story_5032_50320501_41_dialog_content = "I have yet to master a lot of usages. It is truly a good tool for the magician.",
  ui_story_5032_50320501_42_dialog_content = "But the guards will snap out of it soon and realize you're gone.",
  ui_story_5032_50320501_43_dialog_content = "Very interesting. I really would like to see a performance sometime.",
  ui_story_5032_50320501_44_dialog_content = "Pretty sure I'll get a chance in the future.",
  ui_story_5032_50320501_45_dialog_content = "Rest assured, I've decided to come clean to you.",
  ui_story_5032_50320501_46_dialog_content = "Just knowing I don't have to hide anything when I talk to you from now on is making me very happy.",
  ui_story_5032_50320501_47_dialog_content = "You ought to know you're still the laird and we have a big mess to clean up.",
  ui_story_5032_50320501_48_dialog_content = "So quit trying to solve problems by force like when you were a kid.",
  ui_story_5032_50320501_49_dialog_content = "Of course. I already told you I'd tell you everything!",
  ui_story_5032_50320501_50_dialog_content = "Hey! Wake up, Loewe!",
  ui_story_5032_50320501_51_dialog_content = "Humph, he's not getting up.",
  ui_story_5032_50320501_52_dialog_content = "Wicked Elvis... That clown Jeno must have done this!",
  ui_story_5032_50320501_53_dialog_content = "Embarrassing me like this... Won't get away even if you're the laird!",
  ui_story_5032_50320501_54_dialog_content = "I'll catch him and then tear him into pieces.",
  ui_story_5032_50320501_55_dialog_content = "Then wipe my shoes with that annoying face of his!",
  ui_story_5032_50320501_56_dialog_content = "All guards, pick up Loewe and come with me to hunt down the fugitive!",
  ui_story_5032_50320501_57_dialog_content = "Yes, sir!",
  ui_story_5032_50320501_58_dialog_content = "Judge Matthieu!",
  ui_story_5032_50320501_59_dialog_content = "What's going on?",
  ui_story_5032_50320501_60_dialog_content = "What's going on, you ask?",
  ui_story_5032_50320501_61_dialog_content = "Not sentencing a criminal but treating him like an honored guest.",
  ui_story_5032_50320501_62_dialog_content = "Is there anything worse than to let him escape?",
  ui_story_5032_50320501_63_dialog_content = "You are saying...",
  ui_story_5032_50320501_64_dialog_content = "Yeah, Elvis escaped.",
  ui_story_5032_50320501_65_dialog_content = "And it's very likely that Jeno helped!",
  ui_story_5032_50320501_66_dialog_content = "I reminded you, Your Highness, to transfer the criminal to Lumopolis as soon as possible.",
  ui_story_5032_50320501_67_dialog_content = "Excuse me, but we got a fugitive to catch, so please stay out of my way!",
  ui_story_5032_50320501_68_dialog_content = "Judge Matthieu looks livid.",
  ui_story_5032_50320501_69_dialog_content = "That's understandable. He's also taken on many responsibilities for supporting my investigation of Elvis.",
  ui_story_5032_50320501_70_dialog_content = "We must act now and catch Elvis.",
  ui_story_5032_50320501_71_dialog_content = "From the clues we have, Elvis should be looking to restart the Windstone.",
  ui_story_5032_50320501_72_dialog_content = "Yes, since that was why he went after the energy core before he was thwarted.",
  ui_story_5032_50320501_73_dialog_content = "Now that he's free, he must be heading for the sealed ground.",
  ui_story_5032_50320501_74_dialog_content = "That's not definite, he could be hiding because he figured we found out about his plan.",
  ui_story_5032_50320501_75_dialog_content = "Regardless, we have to go there, too.",
  ui_story_5032_50320501_76_dialog_content = "Are you up for this, Carleen?",
  ui_story_5032_50320501_77_dialog_content = "I'm fine, worry not.",
  ui_story_5032_50320501_78_dialog_content = "Not to mention we got things to tell him in person.",
  ui_story_5032_50320502_1_dialog_content = "Watch out!",
  ui_story_5032_50320502_2_dialog_content = "Graaah!",
  ui_story_5032_50320502_3_dialog_content = "We got more Eclipsites than before.",
  ui_story_5032_50320502_4_dialog_content = "Even though we're not too far from Harbor City.",
  ui_story_5032_50320502_5_dialog_content = "These Eclipsites... Could it be the Windstone is weakening?",
  ui_story_5032_50320502_6_dialog_content = "Focus! We're almost at the <color=#FFB400>sealed ground</color> marked in Elvis's notes!",
  ui_story_5032_50320502_7_dialog_content = "Got it!",
  ui_story_5032_50320502_8_dialog_content = "All the mysteries will be solved there.",
  ui_story_5032_50320502_9_dialog_content = "Is this it?",
  ui_story_5032_50320502_10_dialog_content = "Yes. The ancestors started the Windstone here to seal the Eclipsites.",
  ui_story_5032_50320502_11_dialog_content = "I'm confident about restarting the stone through the device here.",
  ui_story_5032_50320502_12_dialog_content = "But I shall not be disturbed during the process, so I need your help.",
  ui_story_5032_50320502_13_dialog_content = "Got it.",
  ui_story_5032_50320502_14_dialog_content = "I'll believe you're doing this for the good of the people in Harbor City, for now.",
  ui_story_5032_50320502_15_dialog_content = "<size=30>At least it fits what I've always thought of you in my mind.</size>",
  ui_story_5032_50320502_16_dialog_content = "What's that, Jeno?",
  ui_story_5032_50320502_17_dialog_content = "Nothing. If what you say is true, I'll help for the sake of you and Harbor City.",
  ui_story_5032_50320502_18_dialog_content = "I got nothing to hide from you now, so trust me, Jeno.",
  ui_story_5032_50320502_19_dialog_content = "Also, thank you, Jeno.",
  ui_story_5032_50320502_20_dialog_content = "Elvis! Jeno!",
  ui_story_5032_50320502_21_dialog_content = "There you are, Your Highness.",
  ui_story_5032_50320502_22_dialog_content = "You did come here after all, Elvis.",
  ui_story_5032_50320502_23_dialog_content = "I see Vice and PlayerName have come too, all familiar and reassuring faces.",
  ui_story_5032_50320502_24_dialog_content = "You shouldn't be moving around in your condition, Elvis.",
  ui_story_5032_50320502_25_dialog_content = "I know that, Miss Vice. I appreciate your concern for a criminal like me.",
  ui_story_5032_50320502_26_dialog_content = "But I got something I must do.",
  ui_story_5032_50320502_27_dialog_content = "Since you're here, I guess you've read my notes in the library.",
  ui_story_5032_50320502_28_dialog_content = "Yes.",
  ui_story_5032_50320502_29_dialog_content = "We know your intent to use the Emerald's energy core to power the Windstone.",
  ui_story_5032_50320502_30_dialog_content = "We also know the stone's purpose, specifically how important it is to Harbor City.",
  ui_story_5032_50320502_31_dialog_content = "But your good intention can't cover your guilt.",
  ui_story_5032_50320502_32_dialog_content = "I knew I couldn't keep it a secret from you.",
  ui_story_5032_50320502_33_dialog_content = "However, since you already figured out my plan, I got nothing more to hide.",
  ui_story_5032_50320502_34_dialog_content = "You're right. I'm a criminal.",
  ui_story_5032_50320502_35_dialog_content = "But I don't have much choice when it comes to protecting the people of Harbor City, the city's foundation, and the Windstone.",
  ui_story_5032_50320502_36_dialog_content = "If it wasn't for the bloodline's power dwindling and the Windstone running on fumes...",
  ui_story_5032_50320502_37_dialog_content = "Perhaps I could find another, better way.",
  ui_story_5032_50320502_38_dialog_content = "But I'm running out of time with my own body, as well as with Eclipsites.",
  ui_story_5032_50320502_39_dialog_content = "I cannot risk it on whether I'll find the optimal solution or die from the Modali Syndrome first.",
  ui_story_5032_50320502_40_dialog_content = "The only thing I know is to trade my final moments for Harbor City's future.",
  ui_story_5032_50320502_41_dialog_content = "You and the Caelestite are the biggest variable in my plan, Your Highness.",
  ui_story_5032_50320502_42_dialog_content = "I was hoping to delay you before coming here to recharge the stone.",
  ui_story_5032_50320502_43_dialog_content = "But not even the <color=#FFB400>Lumothread</color> specifically tailored for you could stop you.",
  ui_story_5032_50320502_44_dialog_content = "...",
  ui_story_5032_50320502_45_dialog_content = "Excuse me, but are you still wearing that dress?",
  ui_story_5032_50320502_46_dialog_content = "It should still be absorbing your Lumina.",
  ui_story_5032_50320502_47_dialog_content = "Yes, it probably hit the limit last time though.",
  ui_story_5032_50320502_48_dialog_content = "PlayerName could sense the Lumina within the dress partly dissipating every day before it absorbs more from me.",
  ui_story_5032_50320502_49_dialog_content = "I actually treat such weak absorption as a means of exercising control over Lumina now.",
  ui_story_5032_50320502_50_dialog_content = "So the Lumothread is now just a part of the training to control Lumina for you...?",
  ui_story_5032_50320502_51_dialog_content = "How amazing...",
  ui_story_5032_50320502_52_dialog_content = "I know I have no right to make any request because of what I've done, Your Highness.",
  ui_story_5032_50320502_53_dialog_content = "But I still beg you...",
  ui_story_5032_50320502_54_dialog_content = "Allow me to recharge the Windstone before taking me in.",
  ui_story_5032_50320502_55_dialog_content = "I believe you and the Hall of Justice will give me a fair trial.",
  ui_story_5032_50320502_56_dialog_content = "But I have a mission that I, Elvis Modali, must fulfill.",
  ui_story_5032_50320502_57_dialog_content = "And that is my final request as the laird of Harbor City.",
  ui_story_5032_50320502_58_dialog_content = "Understood.",
  ui_story_5032_50320502_59_dialog_content = "Considering your track record of running Harbor City and protecting its people...",
  ui_story_5032_50320502_60_dialog_content = "I'll help you until the Windstone functions again and the city is safe once more.",
  ui_story_5032_50320502_61_dialog_content = "I'm very grateful, Your Highness.",
  ui_story_5032_50320502_62_dialog_content = "I may be a fugitive, but please allow me to thank you as the laird of Harbor City.",
  ui_story_5032_50320502_63_dialog_content = "Let's dispense with formalities. Please recharge the stone as soon as possible.",
  ui_story_5032_50320502_64_dialog_content = "Rest assured, I've been working on awakening the sealed ground.",
  ui_story_5032_50320502_65_dialog_content = "I'm glad I was not wrong about you. When I knew you, I could sense you're different from the other nobles.",
  ui_story_5032_50320502_66_dialog_content = "Forgive me for not completely trusting anyone new from Lumopolis.",
  ui_story_5032_50320502_67_dialog_content = "Because I'm sure many in the Elder Council covet the power that safeguards Harbor City.",
  ui_story_5032_50320502_68_dialog_content = "Alas, if only I had trusted you more from the start and not suspected you to be selfish like those nobles...",
  ui_story_5032_50320502_69_dialog_content = "Perhaps everything would have turned out better, then.",
  ui_story_5032_50320502_70_dialog_content = "But there's still a chance.",
  ui_story_5032_50320502_71_dialog_content = "I understand how you feel about what the Elder Council might think toward the energy core or Windstone.",
  ui_story_5032_50320502_72_dialog_content = "I, however, will never try to undermine what the foundation of Harbor City.",
  ui_story_5032_50320502_73_dialog_content = "The Eclipsites are the common enemy, after all, and you will receive a fair trial for your missteps.",
  ui_story_5032_50320502_74_dialog_content = "But for now, I can promise that no Eclipsites will come near you.",
  ui_story_5032_50320502_75_dialog_content = "Thank you, Your Highness.",
  ui_story_5032_50320502_76_dialog_content = "Let's begin, then.",
  ui_story_5032_50320502_77_dialog_content = "Turn a new page in Harbor City history.",
  ui_story_5032_50320601_1_dialog_content = "The restart of Windstone, now begins.",
  ui_story_5032_50320601_2_dialog_content = "Restarting...",
  ui_story_5032_50320601_3_dialog_content = "Appropriate Aurorian genes detected... Initiating Lumina extraction.",
  ui_story_5032_50320601_4_dialog_content = "Yes, this is the spot. Follow what's in the book... Cough... And redirect the energy flow.",
  ui_story_5032_50320601_5_dialog_content = "Just... use the device on the sealed ground.",
  ui_story_5032_50320601_6_dialog_content = "Redirection request detected. Redirect energy source.",
  ui_story_5032_50320601_7_dialog_content = "Connecting...",
  ui_story_5032_50320601_8_dialog_content = "1%... 7%... 19%...",
  ui_story_5032_50320601_9_dialog_content = "We just wait for the process to finish now?",
  ui_story_5032_50320601_10_dialog_content = "Exactly.",
  ui_story_5032_50320601_11_dialog_content = "If the restart is successful, the Windstone will adopt the <color=#FFB400>energy absorbed</color> from the core as the new source.",
  ui_story_5032_50320601_12_dialog_content = "Then, those chronically troubled by <color=#FFB400>Modali Syndrome</color> will finally be free... *Coughing*",
  ui_story_5032_50320601_13_dialog_content = "Yeah... That should improve your condition too, right?",
  ui_story_5032_50320601_14_dialog_content = "Haha, probably.",
  ui_story_5032_50320601_15_dialog_content = "No idea how much better I'll be, but definitely better than I am now.",
  ui_story_5032_50320601_16_dialog_content = "After the mess I caused, I can't lead Harbor City anymore though.",
  ui_story_5032_50320601_17_dialog_content = "It's true that your action seriously violated your obligations as the laird, but it was basically for the good of the people.",
  ui_story_5032_50320601_18_dialog_content = "I will explain it to the City Lord to get you a fair judgment.",
  ui_story_5032_50320601_19_dialog_content = "Heh, you are indeed different, Your Highness. Allow me to express my gratitude again.",
  ui_story_5032_50320601_20_dialog_content = "If you got nowhere to go, Elvis... you could consider coming aboard the Emerald.",
  ui_story_5032_50320601_21_dialog_content = "Oh? But I'm not a circus performer, Jeno.",
  ui_story_5032_50320601_22_dialog_content = "It's cool. You can learn.",
  ui_story_5032_50320601_23_dialog_content = "We just need an alternate tamer, anyway.",
  ui_story_5032_50320601_24_dialog_content = "That means I'll have to work very hard, then.",
  ui_story_5032_50320601_25_dialog_content = "(Elvis is looking a lot more relaxed. Guess they've made up.)",
  ui_story_5032_50320601_26_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5032_50320601_27_dialog_content = "Why is Windstone making all that noise?",
  ui_story_5032_50320601_28_dialog_content = "What's going on?",
  ui_story_5032_50320601_29_dialog_content = "Warning. Energy redirection error.",
  ui_story_5032_50320601_30_dialog_content = "Error Code 102. Energy incompatible with <color=#FFB400>Windstone</color>.",
  ui_story_5032_50320601_31_dialog_content = "Impossible! My research showed the energy from the energy core is the most compatible with the stone!",
  ui_story_5032_50320601_32_dialog_content = "Don't panic, Elvis!",
  ui_story_5032_50320601_33_dialog_content = "Check the stone and see if there's anything we can do.",
  ui_story_5032_50320601_34_dialog_content = "I shall... What is this?!",
  ui_story_5032_50320601_35_dialog_content = "What's wrong?",
  ui_story_5032_50320601_36_dialog_content = "The output rate of the energy core is fluctuating... and getting increasingly intense!",
  ui_story_5032_50320601_37_dialog_content = "That happens only when the energy is not pure enough!",
  ui_story_5032_50320601_38_dialog_content = "Warning. Critical error in energy redirection.",
  ui_story_5032_50320601_39_dialog_content = "Error Code 600. Energy influx exceeds <color=#FFB400>Windstone</color> capacity.",
  ui_story_5032_50320601_40_dialog_content = "Halt energy input immediately to avoid severe repercussions.",
  ui_story_5032_50320601_41_dialog_content = "Shut it down, Elvis, or it's going to blow!",
  ui_story_5032_50320601_42_dialog_content = "I'm... trying...",
  ui_story_5032_50320601_43_dialog_content = "Ugh!!!",
  ui_story_5032_50320601_44_dialog_content = "Vice, protect PlayerName!",
  ui_story_5032_50320601_45_dialog_content = "Get behind us, PlayerName!",
  ui_story_5032_50320601_46_dialog_content = "Elvis!",
  ui_story_5032_50320601_47_dialog_content = "Don't come close... The energy... is starting to leak!",
  ui_story_5032_50320601_48_dialog_content = "I can't stop it!",
  ui_story_5032_50320601_49_dialog_content = "Never mind the scepter, just drop it!",
  ui_story_5032_50320601_50_dialog_content = "<color=#e8d9bb>BOOM!!!</color>",
  ui_story_5032_50320601_51_dialog_content = "Uh!",
  ui_story_5032_50320601_52_dialog_content = "*Coughs*",
  ui_story_5032_50320601_53_dialog_content = "Are you okay, Jeno?!",
  ui_story_5032_50320601_54_dialog_content = "*Coughs*... I'm fine, still alive.",
  ui_story_5032_50320601_55_dialog_content = "If I was any slower, you'd be dead.",
  ui_story_5032_50320601_56_dialog_content = "The Windstone... is out of control...!",
  ui_story_5032_50320601_57_dialog_content = "The Windstone! Is the Windstone fine?!",
  ui_story_5032_50320601_58_dialog_content = "Elvis!",
  ui_story_5032_50320601_59_dialog_content = "Here it is... Fortunately, it's not damaged, yet all of its energy has been lost.",
  ui_story_5032_50320601_60_dialog_content = "Maybe it can still be restarted!",
  ui_story_5032_50320601_61_dialog_content = "Restarted?",
  ui_story_5032_50320601_62_dialog_content = "Look, Elvis, the sealed ground has been ruined beyond recognition by the explosion.",
  ui_story_5032_50320601_63_dialog_content = "The ancient devices are wrecked. How are we going to restart?",
  ui_story_5032_50320601_64_dialog_content = "I... Give me more time and I'll figure out a way!",
  ui_story_5032_50320601_65_dialog_content = "Help, help! Eclipsites!",
  ui_story_5032_50320601_66_dialog_content = "Eclipsites?!",
  ui_story_5032_50320601_67_dialog_content = "The sound seems to come from the town.",
  ui_story_5032_50320601_68_dialog_content = "*Coughs*... Oh no, Eclipsites must have broken the seal because the Windstone lost all the energy!",
  ui_story_5032_50320601_69_dialog_content = "<color=#e8d9bb>Meanwhile, in Harbor City</color>",
  ui_story_5032_50320601_70_dialog_content = "Why are so many Eclipsites coming out of the ocean?!",
  ui_story_5032_50320601_71_dialog_content = "Quick, get to the coast! Set up defenses and evacuate the people!",
  ui_story_5032_50320601_72_dialog_content = "Yes, sir!",
  ui_story_5032_50320601_73_dialog_content = "Eclipsites appear along the coast?",
  ui_story_5032_50320601_74_dialog_content = "And the sound of an explosion coming from the sealed ground just now... Did Laird Elvis fail?",
  ui_story_5032_50320601_75_dialog_content = "I gotta protect the laird. With all the soldiers off to fight Eclipsites, now is the time.",
  ui_story_5032_50320601_76_dialog_content = "Follow me, everyone!",
  ui_story_5032_50320601_77_dialog_content = "Yes!!!",
  ui_story_5032_50320601_78_dialog_content = "Laird Elvis!",
  ui_story_5032_50320601_79_dialog_content = "Patou? What are you doing here?",
  ui_story_5032_50320601_80_dialog_content = "Huff, huff...",
  ui_story_5032_50320601_81_dialog_content = "You sure didn't make it easy for me to find, Elvis, and Patou.",
  ui_story_5032_50320601_82_dialog_content = "Your face's twisting.",
  ui_story_5032_50320601_83_dialog_content = "Not even trying to hide?",
  ui_story_5032_50320601_84_dialog_content = "Now is not the time for your snark!",
  ui_story_5032_50320601_85_dialog_content = "Can't you see it's urgent right now? Don't get in the way!",
  ui_story_5032_50320601_86_dialog_content = "Jeno is right. Harbor City is in danger.",
  ui_story_5032_50320601_87_dialog_content = "Wait... Why are you here, Your Highness?",
  ui_story_5032_50320601_88_dialog_content = "I'll get to that later. We got much more important issues at hand.",
  ui_story_5032_50320601_89_dialog_content = "*Coughs*... How is Harbor City, Patou?",
  ui_story_5032_50320601_90_dialog_content = "Countless Eclipsites are coming out of the sea, sir. The Windstone is probably ineffective now.",
  ui_story_5032_50320601_91_dialog_content = "I was afraid of that...",
  ui_story_5032_50320601_92_dialog_content = "Vice, PlayerName, let's get back to town.",
  ui_story_5032_50320601_93_dialog_content = "There are so many unarmed citizens. We cannot sit by idly!",
  ui_story_5032_50320601_94_dialog_content = "Yeah, got it!",
  ui_story_5032_50320601_95_dialog_content = "Sure!",
  ui_story_5032_50320601_96_dialog_content = "But wait... What about the prison escapee?",
  ui_story_5032_50320601_97_dialog_content = "Jeno, please... Go with Her Highness.",
  ui_story_5032_50320601_98_dialog_content = "And please... protect the people of Harbor City.",
  ui_story_5032_50320601_99_dialog_content = "No, I'm staying here with you.",
  ui_story_5032_50320601_100_dialog_content = "Don't you realize you're on your last legs?",
  ui_story_5032_50320601_101_dialog_content = "Don't worry, Jeno, I can still go.",
  ui_story_5032_50320601_102_dialog_content = "*Coughs* I... got to get back. There should be clues about restarting Windstone in the files.",
  ui_story_5032_50320601_103_dialog_content = "If I can restart it, the Eclipsites will go away.",
  ui_story_5032_50320601_104_dialog_content = "You better find something to get rid of the Eclipsites.",
  ui_story_5032_50320601_105_dialog_content = "I'm not letting a fugitive move around freely. Loewe and I will be watching you!",
  ui_story_5032_50320601_106_dialog_content = "Heh, thanks for the thought.",
  ui_story_5032_50320601_107_dialog_content = "Elvis...",
  ui_story_5032_50320601_108_dialog_content = "It's okay, Jeno. I'll be all right with Patou and others around.",
  ui_story_5032_50320601_109_dialog_content = "Please take care of the people in Harbor City for me.",
  ui_story_5032_50320601_110_dialog_content = "...",
  ui_story_5032_50320601_111_dialog_content = "You sure know how to toss me the hot potatoes.",
  ui_story_5032_50320601_112_dialog_content = "I'm sorry... I'll make it up to you when this is over.",
  ui_story_5032_50320601_113_dialog_content = "As long as it's within my ability.",
  ui_story_5032_50320601_114_dialog_content = "Fine, I'll wait for you.",
  ui_story_5032_50320601_115_dialog_content = "Okay.",
  ui_story_5032_50320601_116_dialog_content = "Um... Why are we getting so many Eclipsites?",
  ui_story_5032_50320601_117_dialog_content = "Look over there!",
  ui_story_5032_50320601_118_dialog_content = "They're growing in number!",
  ui_story_5032_50320601_119_dialog_content = "How is that possible...",
  ui_story_5032_50320601_120_dialog_content = "The sea is full of Eclipsites!",
  ui_story_5032_50320601_121_dialog_content = "Stop thinking and start fighting!",
  ui_story_5032_50320601_122_dialog_content = "Is it possible to even fight them all?",
  ui_story_5032_50320601_123_dialog_content = "We have no choice but to fight.",
  ui_story_5032_50320601_124_dialog_content = "We must stand our ground and protect the people of Harbor City.",
  ui_story_5032_50320601_125_dialog_content = "I'm not backing up until the civilians are evacuated!",
  ui_story_5032_50320601_126_dialog_content = "... Elvis is right. You are different from the other nobles.",
  ui_story_5032_50320601_127_dialog_content = "Let me help. This is once our home, after all.",
  ui_story_5032_50320602_1_dialog_content = "Ugh... Pooh! This is salty!",
  ui_story_5032_50320602_2_dialog_content = "Got to watch out for not only the Eclipsites but the raging sea too...",
  ui_story_5032_50320602_3_dialog_content = "I wonder if Fia and others will be okay on the <color=#FFB400>Emerald</color>.",
  ui_story_5032_50320602_4_dialog_content = "It should be all right with Rainbow and Ciel there, I guess.",
  ui_story_5032_50320602_5_dialog_content = "Not really... The Emerald is like a lone island with all these Eclipsites in the water.",
  ui_story_5032_50320602_6_dialog_content = "People on shore can still retreat, but the Emerald has nowhere to go.",
  ui_story_5032_50320602_7_dialog_content = "We must go help them!",
  ui_story_5032_50320602_8_dialog_content = "But what about here...?",
  ui_story_5032_50320602_9_dialog_content = "I got this. With Jeno's help, it will be fine!",
  ui_story_5032_50320602_10_dialog_content = "You go help Fia!",
  ui_story_5032_50320602_11_dialog_content = "OK, got it!",
  ui_story_5032_50320602_12_dialog_content = "You sure the two of them can handle it?",
  ui_story_5032_50320602_13_dialog_content = "Yes.",
  ui_story_5032_50320602_14_dialog_content = "As their friend, I know how tough they are, better than anyone.",
  ui_story_5032_50320602_15_dialog_content = "Trust me. They will bring your crew to safety.",
  ui_story_5032_50320602_16_dialog_content = "Since you put it that way...",
  ui_story_5032_50320602_17_dialog_content = "Gahhhh!!!",
  ui_story_5032_50320602_18_dialog_content = "Tsk...",
  ui_story_5032_50320602_19_dialog_content = "Why are there so many Eclipsites? It's been endless.",
  ui_story_5032_50320602_20_dialog_content = "They've been trapped undersea for so long. They'd certainly run rampant now that the seal was broken.",
  ui_story_5032_50320602_21_dialog_content = "You can imagine how much energy the Windstone needed to maintain such a powerful seal.",
  ui_story_5032_50320602_22_dialog_content = "Now is not the time for speculations. We got a fight on our hands!",
  ui_story_5032_50320602_23_dialog_content = "Sure.",
  ui_story_5032_50320602_24_dialog_content = "Grah...",
  ui_story_5032_50320602_25_dialog_content = "Your Highness!",
  ui_story_5032_50320602_26_dialog_content = "There are too many Eclipsites, and the coastline is too long for us to set up an effective line of defense!",
  ui_story_5032_50320602_27_dialog_content = "We're outnumbered, but we may still have a chance if we concentrate our forces on the town.",
  ui_story_5032_50320602_28_dialog_content = "Can't do. We haven't evacuated everyone yet!",
  ui_story_5032_50320602_29_dialog_content = "Well, seems like there's no choice... Get the guards to protect the gates and the civilians. We'll abandon the rest coastal defense areas in order!",
  ui_story_5032_50320602_30_dialog_content = "Regardless, hold until all people are evacuated.",
  ui_story_5032_50320602_31_dialog_content = "As you command!",
  ui_story_5032_50320701_1_dialog_content = "Graagh!",
  ui_story_5032_50320701_2_dialog_content = "Ahhh, they sure broke this window too!",
  ui_story_5032_50320701_3_dialog_content = "Water and shattered glass are everywhere. This can't get any worse...",
  ui_story_5032_50320701_4_dialog_content = "I can't afford to hire cleaners, nor can I clean this up all by myself!",
  ui_story_5032_50320701_5_dialog_content = "Graaaah!",
  ui_story_5032_50320701_6_dialog_content = "T-Take it easy, Rainbow. I'll help you with the mess later.",
  ui_story_5032_50320701_7_dialog_content = "There are more and more Eclipsites, so let's be careful.",
  ui_story_5032_50320701_8_dialog_content = "Ciel, Fia, please board up the window as you did before.",
  ui_story_5032_50320701_9_dialog_content = "I'll get rid of these creeps!",
  ui_story_5032_50320701_10_dialog_content = "Grrrr!",
  ui_story_5032_50320701_11_dialog_content = "R-Rainbow!",
  ui_story_5032_50320701_12_dialog_content = "... She's charged headlong into the battle as usual.",
  ui_story_5032_50320701_13_dialog_content = "Eclipsites are the only thing on her mind when she sees them.",
  ui_story_5032_50320701_14_dialog_content = "Will Rainbow be okay?",
  ui_story_5032_50320701_15_dialog_content = "She already defeated a lot of them, and she's wounded.",
  ui_story_5032_50320701_16_dialog_content = "Even though that's all self-inflicted in her excitement...",
  ui_story_5032_50320701_17_dialog_content = "I'm kind of worried too.",
  ui_story_5032_50320701_18_dialog_content = "Hmm, I blame it on me not operating Styx properly before.",
  ui_story_5032_50320701_19_dialog_content = "Or I wouldn't be standing by so helplessly...",
  ui_story_5032_50320701_20_dialog_content = "Me too.",
  ui_story_5032_50320701_21_dialog_content = "If only I hadn't tossed Kyllo into the sea.",
  ui_story_5032_50320701_22_dialog_content = "With Kyllo around, these Eclipsites would be easy pickings!",
  ui_story_5032_50320701_23_dialog_content = "Alas. At least this should be the last window, and we can lock the Eclipsites out of it soon.",
  ui_story_5032_50320701_24_dialog_content = "All right, I'm boarding this side up. Give me a hand, Fia...",
  ui_story_5032_50320701_25_dialog_content = "Grrr!",
  ui_story_5032_50320701_26_dialog_content = "Ugh! A-Another Eclipsite!",
  ui_story_5032_50320701_27_dialog_content = "Get away, Fia!",
  ui_story_5032_50320701_28_dialog_content = "Gahh!",
  ui_story_5032_50320701_29_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5032_50320701_30_dialog_content = "Fia!",
  ui_story_5032_50320701_31_dialog_content = "Oh no, the Eclipsite is too close to her for me to use Aqua Blaster!",
  ui_story_5032_50320701_32_dialog_content = "In that case...",
  ui_story_5032_50320701_33_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5032_50320701_34_dialog_content = "Grrr!",
  ui_story_5032_50320701_35_dialog_content = "Uh!",
  ui_story_5032_50320701_36_dialog_content = "Rainbow! Fia! Are you guys okay?",
  ui_story_5032_50320701_37_dialog_content = "Um...",
  ui_story_5032_50320701_38_dialog_content = "I-I'm fine. My head just hurts a bit.",
  ui_story_5032_50320701_39_dialog_content = "Where's Rainbow? I think I saw her coming my way.",
  ui_story_5032_50320701_40_dialog_content = "...",
  ui_story_5032_50320701_41_dialog_content = "Oh no, Rainbow passed out!",
  ui_story_5032_50320701_42_dialog_content = "She's got a bloody back!",
  ui_story_5032_50320701_43_dialog_content = "Was she struck by the Eclipsite?",
  ui_story_5032_50320701_44_dialog_content = "She... She got hurt trying to save me...",
  ui_story_5032_50320701_45_dialog_content = "C-Ce, we have nothing to stop the bleeding. W-What to do...",
  ui_story_5032_50320701_46_dialog_content = "I couldn't help PlayerName and my pals when they fought the big robot.",
  ui_story_5032_50320701_47_dialog_content = "Now I can't help Rainbow and Ciel, and I even got Rainbow hurt...",
  ui_story_5032_50320701_48_dialog_content = "<anim type=Shake>Boo-hoo... I... I...</anim>",
  ui_story_5032_50320701_49_dialog_content = "Grrr!",
  ui_story_5032_50320701_50_dialog_content = "No, now's not the time for crying!",
  ui_story_5032_50320701_51_dialog_content = "I must protect Rainbow!",
  ui_story_5032_50320701_52_dialog_content = "Stay away, you stupid Eclipsites!",
  ui_story_5032_50320701_53_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5032_50320701_54_dialog_content = "Graagh!",
  ui_story_5032_50320701_55_dialog_content = "Wow! It worked!",
  ui_story_5032_50320701_56_dialog_content = "I knew it didn't work last time because the robot was too tough...",
  ui_story_5032_50320701_57_dialog_content = "Gah! Gah!",
  ui_story_5032_50320701_58_dialog_content = "Watch out, Fia, here they come again!",
  ui_story_5032_50320701_59_dialog_content = "Ahhhh... Why so many Eclipsites?!",
  ui_story_5032_50320701_60_dialog_content = "Are they migrating through the sea or something all of a sudden?",
  ui_story_5032_50320701_61_dialog_content = "Three shots left, with a spare clip...",
  ui_story_5032_50320701_62_dialog_content = "*Sobs* This isn't enough!",
  ui_story_5032_50320701_63_dialog_content = "Grrr!",
  ui_story_5032_50320701_64_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5032_50320701_65_dialog_content = "If only Kyllo was here...",
  ui_story_5032_50320701_66_dialog_content = "Kyllo!",
  ui_story_5032_50320701_67_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_68_dialog_content = "Gaah!",
  ui_story_5032_50320701_69_dialog_content = "Kyllo? Y-You're here?!",
  ui_story_5032_50320701_70_dialog_content = "Wh-What kind of wondrous beast is this?",
  ui_story_5032_50320701_71_dialog_content = "It's my pal. Its name is Kyllo!",
  ui_story_5032_50320701_72_dialog_content = "A-Awesome! It's overpowering the Eclipsites.",
  ui_story_5032_50320701_73_dialog_content = "Hehe, of course!",
  ui_story_5032_50320701_74_dialog_content = "Kyllo is an evolved exotic!",
  ui_story_5032_50320701_75_dialog_content = "That's a piece of cake for it!",
  ui_story_5032_50320701_76_dialog_content = "Grrr!",
  ui_story_5032_50320701_77_dialog_content = "Look out, Kyllo. Eclipsites are coming up behind you!",
  ui_story_5032_50320701_78_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_79_dialog_content = "Wh-What? You can't turn around?",
  ui_story_5032_50320701_80_dialog_content = "Is it too big to maneuver in the cramped space?",
  ui_story_5032_50320701_81_dialog_content = "Gah—",
  ui_story_5032_50320701_82_dialog_content = "Ah, I-I got to reload!",
  ui_story_5032_50320701_83_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5032_50320701_84_dialog_content = "Oops, I dropped all the bullets!",
  ui_story_5032_50320701_85_dialog_content = "Oh no, Kyllo!",
  ui_story_5032_50320701_86_dialog_content = "Lo!",
  ui_story_5032_50320701_87_dialog_content = "Rapid Torrent!",
  ui_story_5032_50320701_88_dialog_content = "Grrr!",
  ui_story_5032_50320701_89_dialog_content = "Huh? Th-That sounds like...",
  ui_story_5032_50320701_90_dialog_content = "Is everybody okay?",
  ui_story_5032_50320701_91_dialog_content = "Sorry, we got here late. Too many Eclipsites in the way.",
  ui_story_5032_50320701_92_dialog_content = "It's Vice and PlayerName!",
  ui_story_5032_50320701_93_dialog_content = "Humph, I guess we're just background to Fia.",
  ui_story_5032_50320701_94_dialog_content = "Yeah, yeah, I feel very sad!",
  ui_story_5032_50320701_95_dialog_content = "The triplets! Why did you get off the deck?",
  ui_story_5032_50320701_96_dialog_content = "We ran into the Caelestite and Vice up there!",
  ui_story_5032_50320701_97_dialog_content = "They said it's very dangerous outside. Some sort of seal was broken.",
  ui_story_5032_50320701_98_dialog_content = "And all the Eclipsites sleeping undersea woke up!",
  ui_story_5032_50320701_99_dialog_content = "So we blocked off the access from the deck and came to tell—",
  ui_story_5032_50320701_100_dialog_content = "Eh? Wait, is that Rainbow lying over there?",
  ui_story_5032_50320701_101_dialog_content = "I-It is!",
  ui_story_5032_50320701_102_dialog_content = "What happened to her?",
  ui_story_5032_50320701_103_dialog_content = "S-She shielded me...",
  ui_story_5032_50320701_104_dialog_content = "I'm so sorry.",
  ui_story_5032_50320701_105_dialog_content = "Gah! Gah!",
  ui_story_5032_50320701_106_dialog_content = "... We'll pick this up later.",
  ui_story_5032_50320701_107_dialog_content = "Got to eliminate these Eclipsites first!",
  ui_story_5032_50320701_X107_dialog_content = "<color=#e8d9bb>Some time later...</color>",
  ui_story_5032_50320701_108_dialog_content = "S-So they really came out of the ocean floor?",
  ui_story_5032_50320701_109_dialog_content = "Yes. We witnessed Elvis failing his attempt and the wave of Eclipsites swarming the shore.",
  ui_story_5032_50320701_110_dialog_content = "Wouldn't that put Harbor City in great danger?",
  ui_story_5032_50320701_111_dialog_content = "Carleen and Jeno are leading the forces defending the shoreline.",
  ui_story_5032_50320701_112_dialog_content = "And Elvis is trying to find another way to restart the seal.",
  ui_story_5032_50320701_113_dialog_content = "The only thing we can do is make sure everyone's safe and buy Elvis time.",
  ui_story_5032_50320701_114_dialog_content = "Thank you for risking your lives to come here for us.",
  ui_story_5032_50320701_115_dialog_content = "I was too reckless and put Ciel and Fia in danger.",
  ui_story_5032_50320701_116_dialog_content = "If you didn't make it on time...",
  ui_story_5032_50320701_117_dialog_content = "It's okay. You would do the same for us if we were in your position.",
  ui_story_5032_50320701_118_dialog_content = "And Fia would've been in big trouble if it wasn't you.",
  ui_story_5032_50320701_119_dialog_content = "Thank you, Rainbow.",
  ui_story_5032_50320701_120_dialog_content = "I should be thanking you and Kyllo for saving us all!",
  ui_story_5032_50320701_121_dialog_content = "Lo!",
  ui_story_5032_50320701_122_dialog_content = "Oh, how come Kyllo is here?",
  ui_story_5032_50320701_123_dialog_content = "Didn't you let it go back to the sea, Fia?",
  ui_story_5032_50320701_124_dialog_content = "Lo, lo, lo.",
  ui_story_5032_50320701_125_dialog_content = "Um, Kyllo says it squeezed in from the window that Eclipsites broke.",
  ui_story_5032_50320701_126_dialog_content = "It had stayed in the nearby waters before it suddenly got a strange feeling when getting close to the Emerald.",
  ui_story_5032_50320701_127_dialog_content = "A strange feeling? What's it?",
  ui_story_5032_50320701_128_dialog_content = "Lo, lo.",
  ui_story_5032_50320701_129_dialog_content = "You sensed I was in danger and followed my Lumina?",
  ui_story_5032_50320701_130_dialog_content = "Lo!",
  ui_story_5032_50320701_131_dialog_content = "Sensed Fia was in danger?",
  ui_story_5032_50320701_132_dialog_content = "Is that a special ability for Kyllo?",
  ui_story_5032_50320701_133_dialog_content = "It's probably because Kyllo and Fia have a deep bond.",
  ui_story_5032_50320701_134_dialog_content = "So there's a psychic link between them.",
  ui_story_5032_50320701_135_dialog_content = "Lo!",
  ui_story_5032_50320701_136_dialog_content = "I see.",
  ui_story_5032_50320701_137_dialog_content = "Since you're back, Kyllo, does that mean you know where the Cloudwhale is?",
  ui_story_5032_50320701_138_dialog_content = "Lo, lo...",
  ui_story_5032_50320701_139_dialog_content = "Uh... What is that?",
  ui_story_5032_50320701_140_dialog_content = "You've been wandering because you couldn't find any clues?",
  ui_story_5032_50320701_141_dialog_content = "You didn't want to see me because I'd yell at you... Hey, I'm not that mean!",
  ui_story_5032_50320701_142_dialog_content = "Lo!",
  ui_story_5032_50320701_143_dialog_content = "You sound pretty mean right now, Fia.",
  ui_story_5032_50320701_144_dialog_content = "Kyllo really likes you, so you should be nicer to it.",
  ui_story_5032_50320701_145_dialog_content = "Yeah, and Kyllo deserved your sincere thanks for saving everybody too.",
  ui_story_5032_50320701_146_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_147_dialog_content = "Wh-What are you nodding for?",
  ui_story_5032_50320701_148_dialog_content = "Have I not been nice to you?",
  ui_story_5032_50320701_149_dialog_content = "Lo...",
  ui_story_5032_50320701_150_dialog_content = "... Okay, okay, I got it. J-Just stop crying!",
  ui_story_5032_50320701_151_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_152_dialog_content = "Y-You want it now? No hurry...",
  ui_story_5032_50320701_153_dialog_content = "Well, okay, thank... Ahem.",
  ui_story_5032_50320701_154_dialog_content = "Lo?",
  ui_story_5032_50320701_155_dialog_content = "Thank you!",
  ui_story_5032_50320701_156_dialog_content = "<size=45>Thank you for saving us!</size>",
  ui_story_5032_50320701_157_dialog_content = "Lo!",
  ui_story_5032_50320701_158_dialog_content = "And... I'll try not to be mean to you anymore, okay?",
  ui_story_5032_50320701_159_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_160_dialog_content = "D-Don't push your luck!",
  ui_story_5032_50320701_161_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_162_dialog_content = "Okay, okay, got it!",
  ui_story_5032_50320701_163_dialog_content = "Five bags of animal cookies, just for you!",
  ui_story_5032_50320701_164_dialog_content = "Lo!",
  ui_story_5032_50320701_165_dialog_content = "Why does this feel like deja vu?",
  ui_story_5032_50320701_166_dialog_content = "What's up with all these wondrous beasts? They really know how to haggle.",
  ui_story_5032_50320701_167_dialog_content = "Oh, wondrous beast!",
  ui_story_5032_50320701_168_dialog_content = "Merylt, Firmet! Bica and others are still in the room!",
  ui_story_5032_50320701_169_dialog_content = "Oh no, the Eclipsites will spook them!",
  ui_story_5032_50320701_170_dialog_content = "Don't get up yet, Rainbow!",
  ui_story_5032_50320701_171_dialog_content = "I'm fine. Merylt used a med kit on me. I feel better now!",
  ui_story_5032_50320701_172_dialog_content = "Got to save the animals now!",
  ui_story_5032_50320701_173_dialog_content = "Gah—",
  ui_story_5032_50320701_174_dialog_content = "... They sure picked the perfect time, didn't they?",
  ui_story_5032_50320701_175_dialog_content = "L-Leave it to us, Rainbow.",
  ui_story_5032_50320701_176_dialog_content = "Merylt, Subli, are you ready?",
  ui_story_5032_50320701_177_dialog_content = "Yeah! Let's do this!",
  ui_story_5032_50320702_1_dialog_content = "It's over now, Bica, you're going to be okay.",
  ui_story_5032_50320702_2_dialog_content = "I've eliminated all those bad guys!",
  ui_story_5032_50320702_3_dialog_content = "Hai hai...",
  ui_story_5032_50320702_4_dialog_content = "The poor thing is still shaking.",
  ui_story_5032_50320702_5_dialog_content = "Why do I feel like the Eclipsite is not the one that frightens Bica...",
  ui_story_5032_50320702_6_dialog_content = "There's a Glooey here, Rainbow!",
  ui_story_5032_50320702_7_dialog_content = "Gloo!",
  ui_story_5032_50320702_8_dialog_content = "And two more over here!",
  ui_story_5032_50320702_9_dialog_content = "Gloo... Gloo!",
  ui_story_5032_50320702_10_dialog_content = "Good, the Glooeys are fine too.",
  ui_story_5032_50320702_11_dialog_content = "So that just leaves...",
  ui_story_5032_50320702_12_dialog_content = "Eh? What's wrong, Merylt?",
  ui_story_5032_50320702_13_dialog_content = "G-Geedo's missing, Rainbow!",
  ui_story_5032_50320702_14_dialog_content = "Geedo?",
  ui_story_5032_50320702_15_dialog_content = "It was kept in a bottle, so it couldn't move around, right?",
  ui_story_5032_50320702_16_dialog_content = "Yes... S-So the Eclipsites must have...",
  ui_story_5032_50320702_17_dialog_content = "Don't worry. Ciel, Fia, and I will search ahead.",
  ui_story_5032_50320702_18_dialog_content = "You can keep looking for the other animals that got away.",
  ui_story_5032_50320702_19_dialog_content = "O-Okay.",
  ui_story_5032_50320702_20_dialog_content = "Keep your spirits up, Merylt. We still got a lot of missing animals to find!",
  ui_story_5032_50320702_21_dialog_content = "Miniphant, Three-tailed cat, Bouncybound...",
  ui_story_5032_50320702_22_dialog_content = "Let's check out those trashed rooms. We need to look through the warehouses thoroughly!",
  ui_story_5032_50320702_23_dialog_content = "Three-tailed cats like to hide in dark corners when they're frightened.",
  ui_story_5032_50320702_24_dialog_content = "Got it.",
  ui_story_5032_50320702_25_dialog_content = "The Emerald housed so many wondrous beasts, I see.",
  ui_story_5032_50320702_26_dialog_content = "No wonder Fia didn't want to leave.",
  ui_story_5032_50320702_27_dialog_content = "Indeed... Oh, Merylt.",
  ui_story_5032_50320702_28_dialog_content = "What kind of wondrous beast is Geedo? We can help you find it.",
  ui_story_5032_50320702_29_dialog_content = "Uh...",
  ui_story_5032_50320702_30_dialog_content = "It's... uh...",
  ui_story_5032_50320702_31_dialog_content = "A fishlike aquatic creature that Ringmaster Jeno brought back, but we have no idea its exact name.",
  ui_story_5032_50320702_32_dialog_content = "So we just named it Geedo.",
  ui_story_5032_50320702_33_dialog_content = "<size=30>Wow, Merylt managed to finish a complete conversation with PlayerName!</size>",
  ui_story_5032_50320702_34_dialog_content = "<size=30>That's progress!</size>",
  ui_story_5032_50320702_35_dialog_content = "<size=30>Probably because Merylt is really concerned about Geedo.</size>",
  ui_story_5032_50320702_36_dialog_content = "<size=30>Let's leave Merylt and the Caelestite to the task!</size>",
  ui_story_5032_50320702_37_dialog_content = "(... Why are Frimet and Subli smirking at me?)",
  ui_story_5032_50320702_38_dialog_content = "Then we should...",
  ui_story_5032_50320702_39_dialog_content = "Ugh!",
  ui_story_5032_50320702_40_dialog_content = "Grrr!",
  ui_story_5032_50320702_41_dialog_content = "Rainbow!",
  ui_story_5032_50320702_42_dialog_content = "Rainbow!",
  ui_story_5032_50320702_43_dialog_content = "It's coming from where Rainbow is!",
  ui_story_5032_50320702_44_dialog_content = "Ah, Merylt and her sisters are heading that way!",
  ui_story_5032_50320702_45_dialog_content = "Let's go, too, PlayerName!",
  ui_story_5032_50320702_46_dialog_content = "Sure!",
  ui_story_5032_50320702_47_dialog_content = "Fia, Ciel, are you all right?",
  ui_story_5032_50320702_48_dialog_content = "Fia, where's Rainbow?",
  ui_story_5032_50320702_49_dialog_content = "Um... I-I'm over here.",
  ui_story_5032_50320702_50_dialog_content = "... Huh? Wh-What a big eye!",
  ui_story_5032_50320702_51_dialog_content = "What is that thing?",
  ui_story_5032_50320702_52_dialog_content = "Well, I'm guessing it's Geedo.",
  ui_story_5032_50320702_53_dialog_content = "Eh? Geedo?",
  ui_story_5032_50320702_54_dialog_content = "This guy is much bigger. How could it be Geedo?",
  ui_story_5032_50320702_55_dialog_content = "It's like this... I saw an Eclipsite holding up a bottle and staring at Geedo through it in this room.",
  ui_story_5032_50320702_56_dialog_content = "I came in to beat it up, but this coward just chucked and shattered the bottle out of fear.",
  ui_story_5032_50320702_57_dialog_content = "Then a flash came off Geedo, and this is what I saw when I could see again...",
  ui_story_5032_50320702_58_dialog_content = "H-How can it be?",
  ui_story_5032_50320702_59_dialog_content = "Gah...",
  ui_story_5032_50320702_60_dialog_content = "Hey, stop moving! You're crowding me!",
  ui_story_5032_50320702_61_dialog_content = "...",
  ui_story_5032_50320702_62_dialog_content = "Huh? It stopped! Did this Eclipsite understand what Rainbow said?",
  ui_story_5032_50320702_63_dialog_content = "I-It looks like it's passed out?",
  ui_story_5032_50320702_64_dialog_content = "Um, I wonder why this Eclipsite seemed to have been in agony.",
  ui_story_5032_50320702_65_dialog_content = "It held its head and moaned, making the small space even more cramped.",
  ui_story_5032_50320702_66_dialog_content = "But I'm a bit tied up at the moment, too. Otherwise, I'd be glad to put it out of its misery right away.",
  ui_story_5032_50320702_67_dialog_content = "Er... I'm just glad you're safe, Rainbow.",
  ui_story_5032_50320702_68_dialog_content = "Anyways, we need to figure out a way to get her out of here and fast.",
  ui_story_5032_50320702_69_dialog_content = "That's right. Rainbow's back is still wounded...",
  ui_story_5032_50320702_70_dialog_content = "*Sobbing* Please hurry! It's getting tighter and tighter in here!",
  ui_story_5032_50320702_71_dialog_content = "C-Can't you try communicating with Geedo, Fia?",
  ui_story_5032_50320702_72_dialog_content = "Huh?",
  ui_story_5032_50320702_73_dialog_content = "Oh, yeah! You can tell Geedo to stop growing, can't you Fia?",
  ui_story_5032_50320702_74_dialog_content = "Hurry, before Rainbow gets flattened into a pancake!",
  ui_story_5032_50320702_75_dialog_content = "No, wait, there is an Eclipsite in there, too... So maybe a Rainbow-and-Eclipsite sandwich, instead of a pancake?",
  ui_story_5032_50320702_76_dialog_content = "Argh... That doesn't sound appetizing at all.",
  ui_story_5032_50320702_77_dialog_content = "Okay, I'll give it a shot!",
  ui_story_5032_50320702_78_dialog_content = "Um... H-Hello, Geedo.",
  ui_story_5032_50320702_79_dialog_content = "Could you maybe, uh... Go back to your original size?",
  ui_story_5032_50320702_80_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_81_dialog_content = "N-No?",
  ui_story_5032_50320702_82_dialog_content = "But why?!",
  ui_story_5032_50320702_83_dialog_content = "Eep-eep-eep!",
  ui_story_5032_50320702_84_dialog_content = "I see... So you want to stretch out a little because constantly maintaining your smaller form is uncomfortable?",
  ui_story_5032_50320702_85_dialog_content = "But don't you know that if you don't stop growing, you're going to hurt the person who saved you?",
  ui_story_5032_50320702_86_dialog_content = "Eep?",
  ui_story_5032_50320702_87_dialog_content = "That's right! Rainbow here can't change her body's size as you can!",
  ui_story_5032_50320702_88_dialog_content = "... Eep-eep.",
  ui_story_5032_50320702_89_dialog_content = "Ah! So you're willing to cooperate?",
  ui_story_5032_50320702_90_dialog_content = "Guys! Go find me an empty bottle and fill it with some water!",
  ui_story_5032_50320702_91_dialog_content = "Kind of like the one used to hold Geedo earlier!",
  ui_story_5032_50320702_92_dialog_content = "Got it!",
  ui_story_5032_50320702_93_dialog_content = "Good thing we haven't sorted out and thrown away the trash from the festival, huh?",
  ui_story_5032_50320702_94_dialog_content = "That's just because you've been slacking off, Subli! The ringmaster put YOU in charge of taking care of the trash three days ago!",
  ui_story_5032_50320702_95_dialog_content = "Heehee! It all worked out in the end!",
  ui_story_5032_50320702_96_dialog_content = "Will this do, Fia?",
  ui_story_5032_50320702_97_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_98_dialog_content = "Geedo says yes! What do we do next?",
  ui_story_5032_50320702_99_dialog_content = "Eep.",
  ui_story_5032_50320702_100_dialog_content = "Point the bottle at you?",
  ui_story_5032_50320702_101_dialog_content = "Like this?",
  ui_story_5032_50320702_102_dialog_content = "Eep!",
  ui_story_5032_50320702_103_dialog_content = "Ahh!",
  ui_story_5032_50320702_104_dialog_content = "Geedo actually fits in the bottle!",
  ui_story_5032_50320702_105_dialog_content = "Th-That's amazing!",
  ui_story_5032_50320702_106_dialog_content = "Phew... I'm saved!",
  ui_story_5032_50320702_107_dialog_content = "Thank you, Fia. You're my hero!",
  ui_story_5032_50320702_108_dialog_content = "Graagh!",
  ui_story_5032_50320702_109_dialog_content = "Whoops! Almost forgot about you...",
  ui_story_5032_50320702_110_dialog_content = "Graagh?",
  ui_story_5032_50320702_111_dialog_content = "We went through some tough times together, my friend... But it looks like this is where our friendship ends.",
  ui_story_5032_50320702_112_dialog_content = "Now die!",
  ui_story_5032_50320702_113_dialog_content = "Graagh!",
  ui_story_5032_50320702_114_dialog_content = "This guy got his bite back as soon as Geedo went back in the bottle, huh?",
  ui_story_5032_50320702_115_dialog_content = "Wait... Now that you mention it...",
  ui_story_5032_50320702_116_dialog_content = "<size=45>Oh! PlayerName, everyone, listen up!</size>",
  ui_story_5032_50320702_117_dialog_content = "Ahhhh! D-Don't just start yelling like that! We're right here!",
  ui_story_5032_50320702_118_dialog_content = "I suddenly remembered something my master said about the Cloudwhale...",
  ui_story_5032_50320702_119_dialog_content = "\"Its power causes Eclipsites to cower in fear, and that its Lumina can dispel even the thickest Darkflow!\"",
  ui_story_5032_50320702_120_dialog_content = "Could it be that Geedo...",
  ui_story_5032_50320702_121_dialog_content = "Is the Cloudwhale that we've been searching for all this time?",
  ui_story_5032_50320702_122_dialog_content = "It's possible! Geedo's Lumina became much harder to detect after it shrank down to its current size.",
  ui_story_5032_50320702_123_dialog_content = "This might be the reason your master lost track of the Cloudwhale and thought it was in danger, Fia!",
  ui_story_5032_50320702_124_dialog_content = "If Geedo really is the Cloudwhale...",
  ui_story_5032_50320702_125_dialog_content = "Then according to my master, it might be able to save us!",
  ui_story_5032_50320702_126_dialog_content = "Geedo's power was able to slow down that Eclipsite's movements earlier, making it an easy target!",
  ui_story_5032_50320702_127_dialog_content = "That means it might be able to do the same to other Eclipsites!",
  ui_story_5032_50320702_128_dialog_content = "If we can take Geedo somewhere big enough for it to change back to its normal size... Its power might suppress the Eclipsites in an even larger area!",
  ui_story_5032_50320702_129_dialog_content = "Geedo came from the ocean, right? What if we just take it back there?",
  ui_story_5032_50320702_130_dialog_content = "You're right, PlayerName! See? Even you can come up with good ideas every once in a while!",
  ui_story_5032_50320702_131_dialog_content = "But we've already sealed off every single window down here...",
  ui_story_5032_50320702_132_dialog_content = "To reopen them, we'll have to wait until the Emerald's engine systems have been repaired.",
  ui_story_5032_50320702_133_dialog_content = "And according to Subli, the deck is still crawling with Eclipsites. Forcing our way through them would be extremely dangerous.",
  ui_story_5032_50320702_134_dialog_content = "Can you ask Geedo for confirmation, Fia? We need to know if it's really the Cloudwhale and has this kind of power.",
  ui_story_5032_50320702_135_dialog_content = "I... I have no way to confirm that. Sorry...",
  ui_story_5032_50320702_136_dialog_content = "B-But my intuition tells me that Geedo really is the Cloudwhale!",
  ui_story_5032_50320702_137_dialog_content = "That's why... That's why I think we should still give it a shot!",
  ui_story_5032_50320702_138_dialog_content = "Hmm... What do you think, PlayerName?",
  ui_story_5032_50320702_139_dialog_content = "I...",
  ui_story_5032_50320702_140_dialog_content = "I agree. Let's give it a try.",
  ui_story_5032_50320702_141_dialog_content = "Even though Fia can be immature... And stubborn... And even unreliable at times...",
  ui_story_5032_50320702_142_dialog_content = "H-Hey! Is this your way of getting back at me, PlayerName?!",
  ui_story_5032_50320702_143_dialog_content = "Despite all of that, Fia and I have been through plenty of dangerous situations together, and I have full confidence in her skill and expertise as an extrozoologist.",
  ui_story_5032_50320702_144_dialog_content = "That's why I'm willing to trust her intuition this time.",
  ui_story_5032_50320702_145_dialog_content = "Going on the deck would be a death sentence... But if Geedo really is the Cloudwhale, then we might be able to turn the tides in our favor!",
  ui_story_5032_50320702_146_dialog_content = "PlayerName...",
  ui_story_5032_50320702_147_dialog_content = "Well,PlayerName, if you trust Fia's judgment, then so do I.",
  ui_story_5032_50320702_148_dialog_content = "I'll come up to the deck with you two.",
  ui_story_5032_50320702_149_dialog_content = "Vice!",
  ui_story_5032_50320702_150_dialog_content = "You guys make some convincing arguments, you know?",
  ui_story_5032_50320702_151_dialog_content = "Rather than putting all of our hopes on others... It's better to get into the game ourselves and increase everyone's chances of success!",
  ui_story_5032_50320702_152_dialog_content = "Besides, sitting around here won't stop the Emerald from getting torn apart anytime soon.",
  ui_story_5032_50320702_153_dialog_content = "Rainbow... Thank you! Thank you all for believing in me!",
  ui_story_5032_50320702_154_dialog_content = "Haha, it doesn't take much to get you feeling emotional, does it Fia?",
  ui_story_5032_50320702_155_dialog_content = "Alright, that's enough... Let's start planning our next move!",
  ui_story_5032_50320702_156_dialog_content = "I'm sure there will be more Eclipsites on the deck than we can imagine...",
  ui_story_5032_50320801_1_dialog_content = "Princess Carleen! A high-level Eclipsite has appeared near our third left-side defensive position! They're requesting reinforcements!",
  ui_story_5032_50320801_2_dialog_content = "Send the fifth guerilla squadron to assist them.",
  ui_story_5032_50320801_3_dialog_content = "The Eclipsites appear to be decreasing in numbers from the seventh left-side defensive position and beyond.",
  ui_story_5032_50320801_4_dialog_content = "Tell them to send out scouts to assess the situation, and assign any reinforcements they can spare to the central defensive points.",
  ui_story_5032_50320801_5_dialog_content = "Understood!",
  ui_story_5032_50320801_6_dialog_content = "How is the city's evacuation proceeding?",
  ui_story_5032_50320801_7_dialog_content = "The first group of civilians has been safely escorted to the shelter, Princess Carleen.",
  ui_story_5032_50320801_8_dialog_content = "We are still in the process of evacuating the rest of the people.",
  ui_story_5032_50320801_9_dialog_content = "We have also inspected the shelter, and everything seems to be in order.",
  ui_story_5032_50320801_10_dialog_content = "Okay. I see.",
  ui_story_5032_50320801_11_dialog_content = "Continue holding the line! We just received communications from Lumopolis saying that reinforcements will be arriving shortly!",
  ui_story_5032_50320801_12_dialog_content = "Understood!",
  ui_story_5032_50320801_13_dialog_content = "I have to say, I'm honestly surprised at how smoothly the evacuation has been going. The first group of refugees reached the shelter in such a short amount of time...",
  ui_story_5032_50320801_14_dialog_content = "At this rate, the number of casualties should be far lower than I anticipated.",
  ui_story_5032_50320801_15_dialog_content = "Indeed. And we have Laird Elvis to thank for this.",
  ui_story_5032_50320801_16_dialog_content = "The laird conduct regular evacuation drills, so people know exactly how to react during an emergency.",
  ui_story_5032_50320801_17_dialog_content = "I never thought I'd see the day that the drills were finally put to use.",
  ui_story_5032_50320801_18_dialog_content = "Evacuation drills?",
  ui_story_5032_50320801_19_dialog_content = "Yes, Your Highness. Laird Elvis prepares for danger even in times of peace, and pays special attention to the maintenance of these systems and facilities.",
  ui_story_5032_50320801_20_dialog_content = "Even though the shelters haven't been used in years, we perform maintenance on them at least once a year at Laird Elvis' instruction.",
  ui_story_5032_50320801_21_dialog_content = "<size=30>Is this part of your plan as well, Elvis?</size>",
  ui_story_5032_50320801_22_dialog_content = "I beg your pardon, Your...",
  ui_story_5032_50320801_23_dialog_content = "L-Look out, Princess Carleen! An Eclipsite is charging right at you!",
  ui_story_5032_50320801_24_dialog_content = "Gahhhh!",
  ui_story_5032_50320801_25_dialog_content = "Ahhhh!",
  ui_story_5032_50320801_26_dialog_content = "Everyone stay calm! Don't panic!",
  ui_story_5032_50320801_27_dialog_content = "M... My apologies, Your Highness!",
  ui_story_5032_50320801_28_dialog_content = "You were put in danger because we were unable to stop it...",
  ui_story_5032_50320801_29_dialog_content = "I'm okay. Now return to your posts.",
  ui_story_5032_50320801_30_dialog_content = "Do not allow formalities like this to distract you on the battlefield.",
  ui_story_5032_50320801_31_dialog_content = "Understood!",
  ui_story_5032_50320801_32_dialog_content = "Ah! H-Help! Reinforcements!",
  ui_story_5032_50320801_33_dialog_content = "Some Eclipsites have broken through our defensive line, and are heading into the city!",
  ui_story_5032_50320801_34_dialog_content = "Graagh!!",
  ui_story_5032_50320801_35_dialog_content = "That's bad. We don't have any soldiers to spare...",
  ui_story_5032_50320801_36_dialog_content = "Come with me!",
  ui_story_5032_50320801_37_dialog_content = "Y-Yes, Your Highness!",
  ui_story_5032_50320801_38_dialog_content = "Ice Blossom!",
  ui_story_5032_50320801_39_dialog_content = "Graagh!",
  ui_story_5032_50320801_40_dialog_content = "*Cough*...",
  ui_story_5032_50320801_41_dialog_content = "Princess Carleen! Have you been injured?!",
  ui_story_5032_50320801_42_dialog_content = "No, I'm fine. It's just... The Darkflow in the air has gotten so dense that even my senses are starting to be affected.",
  ui_story_5032_50320801_43_dialog_content = "Given the state of our forces, a protracted battle is highly unfavorable.",
  ui_story_5032_50320801_44_dialog_content = "Graagh!",
  ui_story_5032_50320801_45_dialog_content = "More Eclipsites broke through!",
  ui_story_5032_50320801_46_dialog_content = "Our front-line troops are starting to dwindle, as well...",
  ui_story_5032_50320801_47_dialog_content = "D-Don't give up! There are still civilians behind us!",
  ui_story_5032_50320801_48_dialog_content = "W-We can't afford to let them break through this defensive line!",
  ui_story_5032_50320801_49_dialog_content = "Got it!",
  ui_story_5032_50320801_50_dialog_content = "Gahhhh!",
  ui_story_5032_50320801_51_dialog_content = "Wh-What's this?!",
  ui_story_5032_50320801_52_dialog_content = "A high-level Eclipsite! Another high-level Eclipsite has appeared!",
  ui_story_5032_50320801_53_dialog_content = "Don't break formation, everyone! Focus on—!",
  ui_story_5032_50320801_54_dialog_content = "Argh!",
  ui_story_5032_50320801_55_dialog_content = "C-Captain!",
  ui_story_5032_50320801_56_dialog_content = "This Eclipsite...",
  ui_story_5032_50320801_57_dialog_content = "It's no use. Normal soldiers don't stand a chance against it.",
  ui_story_5032_50320801_58_dialog_content = "Pull back for now, and go deal with the other Eclipsites! Don't let a single one enter the city until the evacuation is complete!",
  ui_story_5032_50320801_59_dialog_content = "Leave this Eclipsite to me!",
  ui_story_5032_50320801_60_dialog_content = "Princess Carleen!",
  ui_story_5032_50320801_61_dialog_content = "Gahhhhhh!",
  ui_story_5032_50320802_1_dialog_content = "Ugh!",
  ui_story_5032_50320802_2_dialog_content = "My body still hasn't fully recovered. My strength can't keep up...",
  ui_story_5032_50320802_3_dialog_content = "Not to mention, the Darkflow is so dense, even my body feels heavy.",
  ui_story_5032_50320802_4_dialog_content = "Gahhhh!",
  ui_story_5032_50320802_5_dialog_content = "Even if I can't stop the Darkflow from overrunning the city... I can't allow this Eclipsite to make it past here!",
  ui_story_5032_50320802_6_dialog_content = "I have no choice. I know I promised Vice...",
  ui_story_5032_50320802_7_dialog_content = "You should take it easy for a while, Carleen. Don't rush your recovery.",
  ui_story_5032_50320802_8_dialog_content = "Passing out from your Lumina draining can happen if you're not acclimated yet.",
  ui_story_5032_50320802_9_dialog_content = "So don't force yourself with your new powers until you've recovered, okay?",
  ui_story_5032_50320802_10_dialog_content = "That does sound like something Carleen would do.",
  ui_story_5032_50320802_11_dialog_content = "Okay, I see.",
  ui_story_5032_50320802_12_dialog_content = "I'll take care of myself. Rest assured.",
  ui_story_5032_50320802_13_dialog_content = "I'm sorry, Vice.",
  ui_story_5032_50320802_14_dialog_content = "But if I back down right now, more people will only get hurt.",
  ui_story_5032_50320802_15_dialog_content = "*Inhales* Concentrate and take deep breaths...",
  ui_story_5032_50320802_16_dialog_content = "Gahhhh!",
  ui_story_5032_50320802_17_dialog_content = "Splendid Glow!",
  ui_story_5032_50320802_18_dialog_content = "Gahhhhhh!",
  ui_story_5032_50320802_19_dialog_content = "It worked!",
  ui_story_5032_50320802_20_dialog_content = "Ugh!",
  ui_story_5032_50320802_21_dialog_content = "I should have known my new power would not be so easy to control...",
  ui_story_5032_50320802_22_dialog_content = "Is it still hard for me to force it?",
  ui_story_5032_50320802_23_dialog_content = "Gahhhh!",
  ui_story_5032_50320802_24_dialog_content = "Can't fully dodge this one!",
  ui_story_5032_50320802_25_dialog_content = "But I can still fight with just a leg injured!",
  ui_story_5032_50320802_26_dialog_content = "<color=#e8d9bb>Clang...</color>",
  ui_story_5032_50320802_27_dialog_content = "Phew... Good thing I made it in time, or else I would have to explain all of this to Schwartz and the rest of those nobles. That would not be fun, at all...",
  ui_story_5032_50320802_28_dialog_content = "Pardon me, Princess Carleen! What kind of fighting style is that?",
  ui_story_5032_50320802_29_dialog_content = "Aren't you worried about us? We would be in huge trouble if something happened to you, you know!",
  ui_story_5032_50320802_30_dialog_content = "Huh?",
  ui_story_5032_50320802_31_dialog_content = "I-It's you!",
  ui_story_5032_50320802_32_dialog_content = "What kind of response is that?",
  ui_story_5032_50320802_33_dialog_content = "I just saved your life! You can do better than that!",
  ui_story_5032_50320802_34_dialog_content = "Come on, at least a \"thank you\" would be nice.",
  ui_story_5032_50320802_35_dialog_content = "... Thank you.",
  ui_story_5032_50320802_36_dialog_content = "Are you hurt, Princess Carleen?",
  ui_story_5032_50320802_37_dialog_content = "I'm perfectly fine, Mr. Loewe.",
  ui_story_5032_50320802_38_dialog_content = "Although, if you two were able to reach this place, then that means...",
  ui_story_5032_50320802_39_dialog_content = "Correct, Princess Carleen. I have found a way to reactivate the Windstone.",
  ui_story_5032_50320802_40_dialog_content = "On behalf of all of Harbor City and its people, please allow me to extend my sincerest gratitude.",
  ui_story_5032_50320802_41_dialog_content = "Thank you for defending our soldiers, our people, and our home.",
  ui_story_5032_50320802_42_dialog_content = "There's no need for such formalities. I was only performing my duties.",
  ui_story_5032_50320802_43_dialog_content = "You selflessly risked your life for the sake of Harbor City and its citizenry.",
  ui_story_5032_50320802_44_dialog_content = "When I think upon my previous distrust in you, it fills me with a profound sense of shame.",
  ui_story_5032_50320802_45_dialog_content = "At the very least, please accept my sincerest gratitude.",
  ui_story_5032_50320802_46_dialog_content = "Hey, Loewe! Quit standing around already!",
  ui_story_5032_50320802_47_dialog_content = "Why am I the only one doing all the work now?",
  ui_story_5032_50320802_48_dialog_content = "Get over here and help me clear out the rest of these filthy Eclipsites!",
  ui_story_5032_50320802_49_dialog_content = "I wasn't the only one assigned to protect the little princess, you know!",
  ui_story_5032_50320802_50_dialog_content = "...",
  ui_story_5032_50320802_51_dialog_content = "... You don't have to shout.",
  ui_story_5032_50320802_52_dialog_content = "Laird Elvis, the situation has worsened far beyond my expectations.",
  ui_story_5032_50320802_53_dialog_content = "I've sent word to Lumopolis, but I have no idea when their reinforcements will arrive.",
  ui_story_5032_50320802_54_dialog_content = "The Darkflow in the air has also gotten incredibly dense. At this rate, everyone's lives will be in danger.",
  ui_story_5032_50320802_55_dialog_content = "Despite the scores of Eclipsites that we've defeated, the Darkflow still hangs heavily in the air over Harbor City...",
  ui_story_5032_50320802_56_dialog_content = "We don't have much time left. I leave the Windstone and the seal to you, Elvis.",
  ui_story_5032_50320802_57_dialog_content = "I understand, Princess Carleen. You made the right decisions.",
  ui_story_5032_50320802_58_dialog_content = "But rest assured, now that I have found a way to activate the Windstone... It will all be over soon.",
  ui_story_5032_50320802_59_dialog_content = "What exactly is this method you speak of? Is there anything I can do to help?",
  ui_story_5032_50320802_60_dialog_content = "Just leave the rest to me, Your Highness.",
  ui_story_5032_50320802_61_dialog_content = "All that I ask is that you continue commanding our defenses for a while long.",
  ui_story_5032_50320802_62_dialog_content = "I understand. I will continue leading the soldiers from here, and buy you as much time as you need.",
  ui_story_5032_50320802_63_dialog_content = "I thank you for your trust, and all that you've done for Harbor City, Your Highness.",
  ui_story_5032_50320802_64_dialog_content = "There is one more thing, though it may sound unfair, given the circumstances... I humbly request that you remember your oath from before.",
  ui_story_5032_50320802_65_dialog_content = "That you will keep mine and Harbor City's secret safe, once reinforcements from Lumopolis arrive.",
  ui_story_5032_50320802_66_dialog_content = "I've given you my word that I will keep any information regarding the Windstone a secret, and I have no intention of breaking that promise.",
  ui_story_5032_50320802_67_dialog_content = "Thank you, Your Highness. With your noble and trustworthy character, I'm fully confident that you will make an exceptional ruler someday.",
  ui_story_5032_50320802_68_dialog_content = "Now then, might I ask if you know where Jeno is right now?",
  ui_story_5032_50320802_69_dialog_content = "Jeno? He should be at the fifth defensive position just up ahead.",
  ui_story_5032_50320802_70_dialog_content = "Do you need him for something?",
  ui_story_5032_50320802_71_dialog_content = "Indeed. Could you please send additional troops to fortify his current position? I'm afraid I will need to pull him from the front lines for some time.",
  ui_story_5032_50320802_72_dialog_content = "I see.",
  ui_story_5032_50320802_73_dialog_content = "Well, please allow me to extend my sincerest gratitude again.",
  ui_story_5032_50320802_74_dialog_content = "In addition, I would like to apologize for any injuries or casualties that you and your allies may have suffered.",
  ui_story_5032_50320802_75_dialog_content = "To have known you have been one of my life's greatest honors, Princess Carleen. You will be forever known as a dear friend to Harbor City.",
  ui_story_5032_50320802_76_dialog_content = "<size=30>And now, I can finally begin... to atone for the mistakes that I have made.</size>",
  ui_story_5032_50320802_77_dialog_content = "Please excuse me.",
  ui_story_5032_50320802_78_dialog_content = "... Elvis.",
  ui_story_5032_50320802_79_dialog_content = "Hmm? Is there something else on your mind, Your Highness?",
  ui_story_5032_50320802_80_dialog_content = "... No, nothing.",
  ui_story_5032_50320802_81_dialog_content = "Please be careful.",
  ui_story_5032_50320802_82_dialog_content = "Your concern is very much appreciated, Princess Carleen.",
  ui_story_5032_50320802_83_dialog_content = "I will remain vigilant.",
  ui_story_5032_50320901_1_dialog_content = "Alright, let's go over the plan one last time!",
  ui_story_5032_50320901_2_dialog_content = "In a few minutes, Subli will unlock the door to the deck. When she does, the \"Geedo Squad\" will charge out.",
  ui_story_5032_50320901_3_dialog_content = "PlayerName and Fia will be at our center, and are in charge of commanding and protecting Geedo.",
  ui_story_5032_50320901_4_dialog_content = "Kyllo, Vice, Merylt, and I will surround them and fend off any attackers.",
  ui_story_5032_50320901_5_dialog_content = "Meanwhile, Ciel, Frimet, and Subli will stay belowdecks to lock the door behind us and continue searching for other animals.",
  ui_story_5032_50320901_6_dialog_content = "Any questions?",
  ui_story_5032_50320901_7_dialog_content = "Nope!",
  ui_story_5032_50320901_8_dialog_content = "N-No questions here.",
  ui_story_5032_50320901_9_dialog_content = "*Gulp*",
  ui_story_5032_50320901_10_dialog_content = "What a familiar sound... Are you feeling nervous, Fia?",
  ui_story_5032_50320901_11_dialog_content = "N-N-N-Not at all!!",
  ui_story_5032_50320901_12_dialog_content = "Th-That was Kyllo swollowing just now, n-not me!",
  ui_story_5032_50320901_13_dialog_content = "Lo?",
  ui_story_5032_50320901_14_dialog_content = "Everything will be okay, Fia! Just pretend it's like that carnival game and you'll be fine!",
  ui_story_5032_50320901_15_dialog_content = "After all, it's just a couple of Eclipsites. Nothing to worry about for people like us!",
  ui_story_5032_50320901_16_dialog_content = "Lo, lo!",
  ui_story_5032_50320901_17_dialog_content = "Er... Okay!",
  ui_story_5032_50320901_18_dialog_content = "<size=30>Except Carleen and Vice were the ones who did all the fighting during the competition...</size>",
  ui_story_5032_50320901_19_dialog_content = "Will... will I really be okay? I'm so nervous...",
  ui_story_5032_50320901_20_dialog_content = "And now, without further ado... Let the next round of the game begin!",
  ui_story_5032_50320901_21_dialog_content = "Open the door, Subli!",
  ui_story_5032_50320901_22_dialog_content = "Got it!",
  ui_story_5032_50320902_1_dialog_content = "Can we really defeat all of these Eclipsites?",
  ui_story_5032_50320902_2_dialog_content = "It looks like more and more of them are appearing on the beach!",
  ui_story_5032_50320902_3_dialog_content = "Gahhhh!",
  ui_story_5032_50320902_4_dialog_content = "Argh! Th-There are more coming at us from our flank!",
  ui_story_5032_50320902_5_dialog_content = "It's over for us, isn't it...?",
  ui_story_5032_50320902_6_dialog_content = "Is this how Harbor City will fall? I-I still haven't told her my affection...",
  ui_story_5032_50320902_7_dialog_content = "If you have enough strength to whine and moan like this, then you should still have some fight left in you.",
  ui_story_5032_50320902_8_dialog_content = "Huh? Wh-Who are you?!",
  ui_story_5032_50320902_9_dialog_content = "Begone, vile creatures of the depths.",
  ui_story_5032_50320902_10_dialog_content = "Let the Truth guide you to your fated demise!",
  ui_story_5032_50320902_11_dialog_content = "Gahhhhhh!",
  ui_story_5032_50320902_12_dialog_content = "Hey! It's the ringmaster from the circus!",
  ui_story_5032_50320902_13_dialog_content = "It's Jeno! He's one of Laird Elvis' close friends!",
  ui_story_5032_50320902_14_dialog_content = "I saw him fighting at one of our defensive positions earlier. Did he come to help us after seeing how few of us remain?",
  ui_story_5032_50320902_15_dialog_content = "We're saved!",
  ui_story_5032_50320902_16_dialog_content = "Wow, the ringmaster is insanely strong! He tore through all of those Eclipsites in the blink of an eye!",
  ui_story_5032_50320902_17_dialog_content = "Hmph... Pathetic.",
  ui_story_5032_50320902_18_dialog_content = "Letting weak Eclipsites like this scare you into surrendering, you should be ashamed to call yourselves Harbor City guards.",
  ui_story_5032_50320902_19_dialog_content = "Don't forget all of the smiling faces of the townsfolk who are counting on you to protect them.",
  ui_story_5032_50320902_20_dialog_content = "Your parents, your children, your friends, and family... All of them are in danger.",
  ui_story_5032_50320902_21_dialog_content = "Find your courage and pull yourselves together. Never show this kind of weakness in front of the enemy.",
  ui_story_5032_50320902_22_dialog_content = "Words can be just as devastating as weapons and can change the course of your destiny, as well as those of your comrades-in-arms. Now shut up and focus on the fight!",
  ui_story_5032_50320902_23_dialog_content = "Understood!",
  ui_story_5032_50320902_24_dialog_content = "On to the next one...",
  ui_story_5032_50320902_25_dialog_content = "Mr. Jeno!",
  ui_story_5032_50320902_26_dialog_content = "Hmm? It's you...",
  ui_story_5032_50320902_27_dialog_content = "I've finally found you, Mr. Jeno!",
  ui_story_5032_50320902_28_dialog_content = "What are you doing here? Where's Elvis?",
  ui_story_5032_50320902_29_dialog_content = "I'm here as well, Jeno.",
  ui_story_5032_50320902_30_dialog_content = "Elvis! Are you alright?",
  ui_story_5032_50320902_31_dialog_content = "It's too dangerous here. You need to return to the command post and find Carleen.",
  ui_story_5032_50320902_32_dialog_content = "She's in charge over there, so it should be safer by her side...",
  ui_story_5032_50320902_33_dialog_content = "I was just at the command post asking Her Highness about your whereabouts Jeno. It's why I've come looking for you.",
  ui_story_5032_50320902_34_dialog_content = "Looking... for me? Why?",
  ui_story_5032_50320902_35_dialog_content = "It has to do with reactivating the Windstone.",
  ui_story_5032_50320902_36_dialog_content = "I found a way to do it, but I need your assistance.",
  ui_story_5032_50320902_37_dialog_content = "Understood. What do you need me to do?",
  ui_story_5032_50320902_38_dialog_content = "We must first retreat to a safer location, away from any possible Eclipsite interference. I will explain everything on the way.",
  ui_story_5032_50320902_39_dialog_content = "Hmm...",
  ui_story_5032_50320902_40_dialog_content = "I'm afraid not.",
  ui_story_5032_50320902_41_dialog_content = "Jeno...",
  ui_story_5032_50320902_42_dialog_content = "Save it. This is the one and only thing I refuse to help you with.",
  ui_story_5032_50320902_43_dialog_content = "I don't know where you got the idea to do this...",
  ui_story_5032_50320902_44_dialog_content = "But anyone who overexerts their Lumina like this will most likely die.",
  ui_story_5032_50320902_45_dialog_content = "I'll gladly help you find another way, or even stand at your side and fight to my dying breath...",
  ui_story_5032_50320902_46_dialog_content = "But I refuse to lead you to your death like this.",
  ui_story_5032_50320902_47_dialog_content = "I have no doubts regarding the strength of our friendship or your bravery, Jeno.",
  ui_story_5032_50320902_48_dialog_content = "But under these dire circumstances, I fear there is no other option left to us.",
  ui_story_5032_50320902_49_dialog_content = "This plan will result in the smallest number of sacrifices possible. As the laird of Harbor City, it falls to me to deliver my people from peril.",
  ui_story_5032_50320902_50_dialog_content = "You think your death would be a \"small sacrifice\"? Did you get hit in the head by one of those exploding machines in the sealed grounds?!",
  ui_story_5032_50320902_51_dialog_content = "Do you have any idea how dangerous it would be if I transferred your remaining Lumina in your current state?",
  ui_story_5032_50320902_52_dialog_content = "One small misstep and your Lumina will be completely overdrawn!",
  ui_story_5032_50320902_53_dialog_content = "The risks are indeed great, but there is still a small chance of success, right?",
  ui_story_5032_50320902_54_dialog_content = "Please, Jeno.",
  ui_story_5032_50320902_55_dialog_content = "I have the utmost trust in your ability to control it properly.",
  ui_story_5032_50320902_56_dialog_content = "After all, you are one of the greatest magicians and artists.",
  ui_story_5032_50320902_57_dialog_content = "It's too dangerous. I have no way to guarantee your safety.",
  ui_story_5032_50320902_58_dialog_content = "Laird Elvis.",
  ui_story_5032_50320902_59_dialog_content = "Excuse me for a moment, Jeno.",
  ui_story_5032_50320902_60_dialog_content = "What is it, Patou?",
  ui_story_5032_50320902_61_dialog_content = "I'm terribly sorry to interrupt your conversation.",
  ui_story_5032_50320902_62_dialog_content = "But yet another high-level Eclipsite has appeared. Please retreat to a safe location for the time being!",
  ui_story_5032_50320902_63_dialog_content = "There's nothing to fear, Patou. So long as Jeno is here, I will not come to harm.",
  ui_story_5032_50320902_64_dialog_content = "Now take what soldiers you can find and go reinforce our defenses.",
  ui_story_5032_50320902_65_dialog_content = "The high-level Eclipsite's power can be quite unpredictable. I would feel safer if you were at the forefront of our defenses.",
  ui_story_5032_50320902_66_dialog_content = "But...",
  ui_story_5032_50320902_67_dialog_content = "Quickly, Patou. Our men need you on the frontlines.",
  ui_story_5032_50320902_68_dialog_content = "... Yes, Laird Elvis.",
  ui_story_5032_50320902_69_dialog_content = "Do you see now, Jeno?",
  ui_story_5032_50320902_70_dialog_content = "This endless flood of Eclipsites will drown our remaining forces sooner rather than later.",
  ui_story_5032_50320902_71_dialog_content = "And that is to say nothing of this ever-intensifying Darkflow, which threatens to suffocate any who survive the onslaught.",
  ui_story_5032_50320902_72_dialog_content = "Princess Carleen's reinforcements are all but spent, and our defensive positions are falling to the Eclipsites one by one.",
  ui_story_5032_50320902_73_dialog_content = "For every second we spend debating, another soldier is torn apart by the Eclipsites.",
  ui_story_5032_50320902_74_dialog_content = "And all of this suffering... was brought about by my own hands.",
  ui_story_5032_50320902_75_dialog_content = "But you had no idea that it would come to this! It isn't your fault!",
  ui_story_5032_50320902_76_dialog_content = "Heheh. A mistake is a mistake, and someone must take responsibility for it. Isn't this one of the first lessons taught to our youngest?",
  ui_story_5032_50320902_77_dialog_content = "Besides, I'm still the laird of Harbor City. More than anything, I wish to protect it, and my people.",
  ui_story_5032_50320902_78_dialog_content = "...",
  ui_story_5032_50320902_79_dialog_content = "You once said you wanted to protect me. Remember?",
  ui_story_5032_50320902_80_dialog_content = "... Yes.",
  ui_story_5032_50320902_81_dialog_content = "Protecting someone does not simply mean keeping that person alive, Jeno... Sometimes, it means keeping their dream alive. Wouldn't you agree?",
  ui_story_5032_50320902_82_dialog_content = "My dream is for the people of Harbor City to return to the peaceful and happy lives that they once knew.",
  ui_story_5032_50320902_83_dialog_content = "They may experience more pain along the way and write more sad stories in the pages of our history.",
  ui_story_5032_50320902_84_dialog_content = "But at the very least, they will have a place to call home... A place where their smiles can blossom once again.",
  ui_story_5032_50320902_85_dialog_content = "To see a smile on every single one of their faces has always been my dream.",
  ui_story_5032_50320902_86_dialog_content = "So I ask you once more, Jeno. Will you help me keep my dream alive?",
  ui_story_5032_50320902_87_dialog_content = "... How could you do this to me?",
  ui_story_5032_50320902_88_dialog_content = "What?",
  ui_story_5032_50320902_89_dialog_content = "You're forcing me... to put a knife to your throat and using all of this talk of dreams and righteousness to justify it.",
  ui_story_5032_50320902_90_dialog_content = "I... I'm so sorry, Jeno.",
  ui_story_5032_50320902_91_dialog_content = "For things that happened years ago, on the Emerald, and now as well...",
  ui_story_5032_50320902_92_dialog_content = "I'm truly sorry, Jeno... for everything.",
  ui_story_5032_50320902_93_dialog_content = "I know I'm not worthy of being called your friend, much less the laird of Harbor City.",
  ui_story_5032_50320902_94_dialog_content = "My stubbornness and paranoia are what caused everything to come to this.",
  ui_story_5032_50320902_95_dialog_content = "You were dragged into my problems as well and for that... I can only apologize once again.",
  ui_story_5032_50320902_96_dialog_content = "But if I let this opportunity slip through my hands and allow the Eclipsites to enter my home...",
  ui_story_5032_50320902_97_dialog_content = "I will never forgive myself for the rest of my worthless life.",
  ui_story_5032_50320902_98_dialog_content = "So call me selfish, call me a fool, call me what you will... But I beg of you... Please help me.",
  ui_story_5032_50320902_99_dialog_content = "...",
  ui_story_5032_50320902_100_dialog_content = "*Sigh* Ever since we were kids, I could never change your mind... or turn you down, for that matter.",
  ui_story_5032_50320902_101_dialog_content = "I'll do it, but as soon as I detect even the slightest hint of danger, I'm putting a stop to the entire ritual.",
  ui_story_5032_50320902_102_dialog_content = "Heheh... I have no objections.",
  ui_story_5032_50320902_103_dialog_content = "Now how should we begin?",
  ui_story_5032_50321001_1_dialog_content = "The sealed ground has already been destroyed. To reactivate the Windstone, we have but one last method.",
  ui_story_5032_50321001_2_dialog_content = "Namely, the method employed by our ancestors to activate the Windstone in ages past... A new covenant must be made with the Windstone.",
  ui_story_5032_50321001_3_dialog_content = "But how will we power it?",
  ui_story_5032_50321001_4_dialog_content = "The Windstone's power reserves are almost entirely depleted, it's true.",
  ui_story_5032_50321001_5_dialog_content = "Perhaps it can only be done as before: by using the Lumina of Aurorians to constantly sustain it...",
  ui_story_5032_50321001_6_dialog_content = "To think of it, I truly am a failure...",
  ui_story_5032_50321001_7_dialog_content = "No... You've done all you can, Elvis. This isn't your fault.",
  ui_story_5032_50321001_8_dialog_content = "Even so, talking about this will not help our situation. We must keep our minds on the Windstone.",
  ui_story_5032_50321001_9_dialog_content = "To activate the Windstone, my ancestors created the sealed ground.",
  ui_story_5032_50321001_10_dialog_content = "Through the sealed ground, the Windstone can establish a sort of link with Aurorians, allowing it to gather their Lumina.",
  ui_story_5032_50321001_11_dialog_content = "*Cough, cough* The sealed ground's capabilities... are not entirely dissimilar to the <color=#FFB400>power</color> you command.",
  ui_story_5032_50321001_12_dialog_content = "You wish to use my powers to simulate the sealed ground's effects and safely reactivate the Windstone. Is that it?",
  ui_story_5032_50321001_13_dialog_content = "Indeed.",
  ui_story_5032_50321001_14_dialog_content = "... Alright, I'll go along with your plan.",
  ui_story_5032_50321001_15_dialog_content = "But as I said before: the second I sense even the slightest danger, I'm severing the connection between you and the Windstone.",
  ui_story_5032_50321001_16_dialog_content = "Very well... I leave the rest to you, my friend.",
  ui_story_5032_50321001_17_dialog_content = "For the sake of Harbor City and its people, the ritual must succeed!",
  ui_story_5032_50321001_18_dialog_content = "Close your eyes, and imagine yourself holding the Windstone in your hands...",
  ui_story_5032_50321001_19_dialog_content = "Hmm...",
  ui_story_5032_50321001_20_dialog_content = "Yes, just like that. I'm about to begin the transfer, so try not to resist.",
  ui_story_5032_50321001_21_dialog_content = "Heheh... I wouldn't dream of it.",
  ui_story_5032_50321001_22_dialog_content = "Establishing the connection between your Lumina and the Windstone...",
  ui_story_5032_50321001_23_dialog_content = "Urgh... *Cough, cough*",
  ui_story_5032_50321001_24_dialog_content = "Alright, I've done what you asked me to do.",
  ui_story_5032_50321001_25_dialog_content = "Get going, Elvis!",
  ui_story_5032_50321001_26_dialog_content = "Windstone! Begin reactivation!",
  ui_story_5032_50321001_27_dialog_content = "Detecting <color=#FFB400>energy</color> input...",
  ui_story_5032_50321001_28_dialog_content = "Aurorian genotype detected... Connection established. Initiating Lumina extraction...",
  ui_story_5032_50321001_29_dialog_content = "Now all I need to do... is...",
  ui_story_5032_50321001_30_dialog_content = "Gahhhhhh!",
  ui_story_5032_50321001_31_dialog_content = "They're gathering all around us. Do they sense the threat of the Windstone's reactivation?",
  ui_story_5032_50321001_32_dialog_content = "Leave these Eclipsites to me.",
  ui_story_5032_50321002_1_dialog_content = "Just... a little more...",
  ui_story_5032_50321002_2_dialog_content = "System reactivation is in progress...",
  ui_story_5032_50321002_3_dialog_content = "*Hack* Argh...!",
  ui_story_5032_50321002_4_dialog_content = "Why is the Windstone absorbing more and more Lumina?!",
  ui_story_5032_50321002_5_dialog_content = "Stop the reactivation, Elvis! Your body can't handle this kind of strain!",
  ui_story_5032_50321002_6_dialog_content = "You'll die at this rate!",
  ui_story_5032_50321002_7_dialog_content = "There's... no stopping now...",
  ui_story_5032_50321002_8_dialog_content = "Just hold on! I'll sever the connection between you and the Windstone!",
  ui_story_5032_50321002_9_dialog_content = "Huh!?",
  ui_story_5032_50321002_10_dialog_content = "Elvis, are you resisting?",
  ui_story_5032_50321002_11_dialog_content = "No... It's the Windstone! It's taken over the link I created so I can't break it!",
  ui_story_5032_50321002_12_dialog_content = "But how could this be? Answer me, Elvis!",
  ui_story_5032_50321002_13_dialog_content = "It seems there is no point in lying to you any further.",
  ui_story_5032_50321002_14_dialog_content = "The truth is that the sealed grounds serve two functions.",
  ui_story_5032_50321002_15_dialog_content = "One is to allow Aurorians to use Lumina to establish a connection with the Windstone so that they may control it.",
  ui_story_5032_50321002_16_dialog_content = "The other is to control the rate at which the Windstone extracts Lumina... in order to prevent it from killing the Aurorians who activate it.",
  ui_story_5032_50321002_17_dialog_content = "You hid the sealed grounds' secondary function from me...",
  ui_story_5032_50321002_18_dialog_content = "You knew that my powers could only simulate the first function!",
  ui_story_5032_50321002_19_dialog_content = "I searched high and low for a way to reactivate the Windstone... One that didn't require the sealed grounds... But in the end...",
  ui_story_5032_50321002_20_dialog_content = "The Windstone had only been activated once in written history. Knowledge on the subject was rather limited.",
  ui_story_5032_50321002_21_dialog_content = "My only choice... was to take a chance...",
  ui_story_5032_50321002_22_dialog_content = "Even if it meant... sacrificing myself.",
  ui_story_5032_50321002_23_dialog_content = "You knew it was going to end like this, didn't you?!",
  ui_story_5032_50321002_24_dialog_content = "Forgive me... Jeno...",
  ui_story_5032_50321002_25_dialog_content = "This was... the only other way I could find...",
  ui_story_5032_50321002_26_dialog_content = "Only by sacrificing myself and offering every last ounce of Lumina in my body... could I guarantee the reactivation of the Windstone! *Cough, cough*",
  ui_story_5032_50321002_27_dialog_content = "How could you deceive me like this?!",
  ui_story_5032_50321002_28_dialog_content = "That's right... I deceived you yet again.",
  ui_story_5032_50321002_29_dialog_content = "Why... Why do I keep doing this to you?",
  ui_story_5032_50321002_30_dialog_content = "I never wanted to hide anything from you... Growing up was the hardest thing I had to do...",
  ui_story_5032_50321002_31_dialog_content = "Heh... But now... I can finally atone for my wrongdoings...",
  ui_story_5032_50321002_32_dialog_content = "This is my fate... as well as the fate of the Modali.",
  ui_story_5032_50321002_33_dialog_content = "By reactivating the Windstone, all of Harbor City will be safe once more...",
  ui_story_5032_50321002_34_dialog_content = "*Cough*",
  ui_story_5032_50321002_35_dialog_content = "Elvis...",
  ui_story_5032_50321002_36_dialog_content = "Are you some kind of idiot?!",
  ui_story_5032_50321002_37_dialog_content = "J-Jeno?!",
  ui_story_5032_50321002_38_dialog_content = "The responsibility of protecting Harbor City isn't yours and yours alone.",
  ui_story_5032_50321002_39_dialog_content = "Don't forget that Harbor City and the Emerald... are my home, as well!",
  ui_story_5032_50321002_40_dialog_content = "You're not the only one onstage, so stop thinking that the spotlight belongs solely to you!",
  ui_story_5032_50321002_41_dialog_content = "No, stop! I don't want to drag you into this!",
  ui_story_5032_50321002_42_dialog_content = "Sever your connection!",
  ui_story_5032_50321002_43_dialog_content = "We haven't seen each other in years... It's not easy to meet up these days, you know...?",
  ui_story_5032_50321002_44_dialog_content = "You think I'll let you get away again so easily?",
  ui_story_5032_50321002_45_dialog_content = "Even though I've always been the passive and immature one...",
  ui_story_5032_50321002_46_dialog_content = "I swore that I'd protect that which I sought to protect.",
  ui_story_5032_50321002_47_dialog_content = "I'm not going back on my word ever again.",
  ui_story_5032_50321002_48_dialog_content = "Jeno...",
  ui_story_5032_50321002_49_dialog_content = "New energy input detected. Establishing connection...",
  ui_story_5032_50321002_50_dialog_content = "It's too late now, Elvis. You and I are on the same sinking ship now.",
  ui_story_5032_50321002_51_dialog_content = "Heh... Heheh... How very like you to do something like this.",
  ui_story_5032_50321002_52_dialog_content = "You're no longer that little boy who needs my protection.",
  ui_story_5032_50321002_53_dialog_content = "Now then... Let's see what kind of magic tricks you have to offer.",
  ui_story_5032_50321002_54_dialog_content = "Ha... For my final act... I'll turn us both into the power source of this stone...",
  ui_story_5032_50321002_55_dialog_content = "<color=#e8d9bb>Meanwhile, aboard the Emerald</color>",
  ui_story_5032_50321002_56_dialog_content = "Gahhhh!",
  ui_story_5032_50321002_57_dialog_content = "Why are there so many Eclipsites here?!",
  ui_story_5032_50321002_58_dialog_content = "Th-There are more of them climbing up the ship's hull!",
  ui_story_5032_50321002_59_dialog_content = "The waters are teeming with Eclipsites! I-I'm too young to get eaten alive!!",
  ui_story_5032_50321002_60_dialog_content = "Gahhhh!!!",
  ui_story_5032_50321002_61_dialog_content = "Fia!",
  ui_story_5032_50321002_62_dialog_content = "Rainbow!",
  ui_story_5032_50321002_63_dialog_content = "Look! There aren't any Eclipsites on the ship's bow! You need to go over there and release Geedo!",
  ui_story_5032_50321002_64_dialog_content = "I'll cut a path for you!",
  ui_story_5032_50321002_65_dialog_content = "I... I have to be strong! For Geedo's sake!",
  ui_story_5032_50321002_66_dialog_content = "Graah! Roar!",
  ui_story_5032_50321002_67_dialog_content = "Get out of my way!",
  ui_story_5032_50321002_68_dialog_content = "We made it to the bow! Now I just have to open the bottle!",
  ui_story_5032_50321002_69_dialog_content = "Ugh!",
  ui_story_5032_50321002_70_dialog_content = "Why is the cap screwed on so tight?!",
  ui_story_5032_50321002_71_dialog_content = "Graaaaaah!",
  ui_story_5032_50321002_72_dialog_content = "Oh no! One of them made it through!",
  ui_story_5032_50321002_73_dialog_content = "Watch out, Fia!",
  ui_story_5032_50321002_74_dialog_content = "Waaaah!!!",
  ui_story_5032_50321002_75_dialog_content = "Graaaaooo!",
  ui_story_5032_50321002_76_dialog_content = "Noooo!!!",
  ui_story_5032_50321002_77_dialog_content = "Fia! Hang onto me!!!",
  ui_story_5032_50321002_78_dialog_content = "Ah—!",
  ui_story_5032_50321002_79_dialog_content = "PlayerName! What are you doing down here, too?!",
  ui_story_5032_50321002_80_dialog_content = "I-I slipped!",
  ui_story_5032_50321002_81_dialog_content = "Nooo! Now I'll never get to eat the candy I stashed away in my room... Is this how it ends for me?!",
  ui_story_5032_50321002_82_dialog_content = "I never got to use all of my hard-earned spending money, either!",
  ui_story_5032_50321002_83_dialog_content = "Glub, glub, glub...",
  ui_story_5032_50321002_84_dialog_content = "(I... I can't breathe...)",
  ui_story_5032_50321002_85_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5032_50321002_86_dialog_content = "All around me... The sound of crashing water...",
  ui_story_5032_50321002_87_dialog_content = "I can breathe again... Could it be that I'm... dead?",
  ui_story_5032_50321002_88_dialog_content = "Don't be silly, PlayerName! You're still alive, and so am I!",
  ui_story_5032_50321002_89_dialog_content = "Open your eyes and see for yourself! Geedo saved us!",
  ui_story_5032_50321002_90_dialog_content = "I-It's massive!!",
  ui_story_5032_50321002_91_dialog_content = "I had no idea Geedo could get this big! Also... Is Geedo flying?!",
  ui_story_5032_50321002_92_dialog_content = "The Cloudwhale is an exotic wondrous beast, after all. Flying isn't really that far out of the question!",
  ui_story_5032_50321002_93_dialog_content = "I have to admit, though, I had no idea Geedo could fly, either...",
  ui_story_5032_50321002_94_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5032_50321002_95_dialog_content = "What was that dull roar just now? Also... Is it me, or do you feel something shaking?",
  ui_story_5032_50321002_96_dialog_content = "Uh-oh... Get down and hold on tight, PlayerName!",
  ui_story_5032_50321002_97_dialog_content = "What?!",
  ui_story_5032_50321002_98_dialog_content = "Huh??",
  ui_story_5032_50321002_99_dialog_content = "Ooooooh!",
  ui_story_5032_50321002_100_dialog_content = "Is it... Is it spouting like a whale?!",
  ui_story_5032_50321002_101_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5032_50321002_102_dialog_content = "What an incredible spout of water! It feels as though we're standing in the rain!",
  ui_story_5032_50321002_103_dialog_content = "Grah! Graaaaaah!",
  ui_story_5032_50321002_104_dialog_content = "Graah... Graaaaah...",
  ui_story_5032_50321002_105_dialog_content = "The water... It looks like it's affecting the Eclipsites!",
  ui_story_5032_50321002_106_dialog_content = "Was Fia right all along?",
  ui_story_5032_50321101_1_dialog_content = "*Coughing* The Eclipsites... Why do their movements seem so sluggish now?",
  ui_story_5032_50321101_2_dialog_content = "The Darkflow appears to be thinning out as well...",
  ui_story_5032_50321101_3_dialog_content = "Could that enormous beast in the sky be responsible for this?",
  ui_story_5032_50321101_4_dialog_content = "Is that... a Cloudwhale?",
  ui_story_5032_50321101_5_dialog_content = "Now that I think about it, that little girl was talking about searching for one before... Fia, I believe?",
  ui_story_5032_50321101_6_dialog_content = "And all this time, I thought she was just a naive little kid chasing after a fairy tale...",
  ui_story_5032_50321101_7_dialog_content = "I never thought she would actually find it!",
  ui_story_5032_50321101_8_dialog_content = "A Cloudwhale?",
  ui_story_5032_50321101_9_dialog_content = "Yes... An incredibly rare type of wondrous beast, one so rare that it has become the stuff of legends... Even I have only seen depictions of it in books.",
  ui_story_5032_50321101_10_dialog_content = "Although its body resembles that of a whale, it's also capable of flight and resides high above the clouds.",
  ui_story_5032_50321101_11_dialog_content = "Its powerful Lumina is capable of deterring Eclipsites and dissipating even the thickest Darkflow.",
  ui_story_5032_50321101_12_dialog_content = "Outside of that, there is precious little knowledge on the Cloudwhales, given how rare they are.",
  ui_story_5032_50321101_13_dialog_content = "I see.",
  ui_story_5032_50321101_14_dialog_content = "You're still fond of reading about legends and tales of fantasy... *Cough, cough*",
  ui_story_5032_50321101_15_dialog_content = "At the very least, it seems we don't have to worry about interference from the nearby Eclipsites for now.",
  ui_story_5032_50321101_16_dialog_content = "You're right... It looks like Harbor City really is blessed by the divine, after all.",
  ui_story_5032_50321101_17_dialog_content = "Not only does the city have a fool for a laird who is willing to risk his life for its sake... but now, it has the protection from one of the rarest wondrous beasts in the entire world.",
  ui_story_5032_50321101_18_dialog_content = "Heheh... Not only that...",
  ui_story_5032_50321101_19_dialog_content = "The city also has a lunatic of a magician... One who is willing to accompany the city laird on all of his foolish endeavors...",
  ui_story_5032_50321101_20_dialog_content = "Harbor City truly is lucky... And so.. am I... *Cough, cough*",
  ui_story_5032_50321101_21_dialog_content = "*Coughing* Urgh!",
  ui_story_5032_50321101_22_dialog_content = "Haa... Am I... at my limit?",
  ui_story_5032_50321101_23_dialog_content = "Just lay down here for now. Try not to speak. You need to save your strength.",
  ui_story_5032_50321101_24_dialog_content = "Since we don't have to worry about the Eclipsites anymore, I have more Lumina to spare.",
  ui_story_5032_50321101_25_dialog_content = "You... you're going to increase your own Lumina input?",
  ui_story_5032_50321101_26_dialog_content = "Urgh... Feeling my Lumina slip away like this... It feels awful.",
  ui_story_5032_50321101_27_dialog_content = "Is this what you've been dealing with all this time, Elvis?",
  ui_story_5032_50321101_28_dialog_content = "Please... Stop it, Jeno! If you keep going... You'll die as well!",
  ui_story_5032_50321101_29_dialog_content = "It's just a little Lumina... I won't let you leave me behind again.",
  ui_story_5032_50321101_30_dialog_content = "This time... I'll stand right in front of you!",
  ui_story_5032_50321101_31_dialog_content = "*Coughs* Jeno...",
  ui_story_5032_50321101_32_dialog_content = "Energy extraction complete.",
  ui_story_5032_50321101_33_dialog_content = "System is ready to activate.",
  ui_story_5032_50321101_34_dialog_content = "Finally had your fill, eh?",
  ui_story_5032_50321101_35_dialog_content = "Who would've guessed such a tiny stone could hold this much Lumina?",
  ui_story_5032_50321101_36_dialog_content = "*Coughing*",
  ui_story_5032_50321101_37_dialog_content = "Elvis! Are you alright?",
  ui_story_5032_50321101_38_dialog_content = "*Gasping* Jeno... When everything has been settled... Please give the Windstone to Patou in my place.",
  ui_story_5032_50321101_39_dialog_content = "I have... already told him... exactly what needs to be done.",
  ui_story_5032_50321101_40_dialog_content = "Elvis...",
  ui_story_5032_50321101_41_dialog_content = "Promise me, Jeno... Promise me that you will deliver the Windstone to Patou.",
  ui_story_5032_50321101_42_dialog_content = "You can give it to him yourself once the seal is reactivated.",
  ui_story_5032_50321101_43_dialog_content = "Please, Jeno... Just help me one last time... I feel so tired...",
  ui_story_5032_50321101_44_dialog_content = "Ever since the day I left you... I have always felt... so very tired...",
  ui_story_5032_50321101_45_dialog_content = "Please... Let me rest awhile, won't you?",
  ui_story_5032_50321101_46_dialog_content = "...",
  ui_story_5032_50321101_47_dialog_content = "I understand.",
  ui_story_5032_50321101_48_dialog_content = "Thank you, Jeno.",
  ui_story_5032_50321101_49_dialog_content = "Thank you... for everything.",
  ui_story_5032_50321101_50_dialog_content = "Windstone... Activate.",
  ui_story_5032_50321101_51_dialog_content = "Command acknowledged.",
  ui_story_5032_50321101_52_dialog_content = "What is that light? It's so bright!",
  ui_story_5032_50321101_53_dialog_content = "It's in the direction of where Laird Elvis went! Could he be in danger?",
  ui_story_5032_50321101_54_dialog_content = "Look! The Eclipsites... They're retreating into the sea!",
  ui_story_5032_50321101_55_dialog_content = "You're right! Even the high-level Eclipsites are backing away!",
  ui_story_5032_50321101_56_dialog_content = "The Darkflow is dissipating! I feel alive again!!",
  ui_story_5032_50321101_57_dialog_content = "It must be Laird Elvis! He must have found a way to rout the Eclipsites!",
  ui_story_5032_50321101_58_dialog_content = "This has to be Laird Elvis' doing!",
  ui_story_5032_50321101_59_dialog_content = "Do you hear that, Elvis?",
  ui_story_5032_50321101_60_dialog_content = "Your people are crying out for you... They're celebrating this victory in your name.",
  ui_story_5032_50321101_61_dialog_content = "You did it. The Windstone and the seal have been reactivated.",
  ui_story_5032_50321101_62_dialog_content = "Heheh... I'm delighted to hear it.",
  ui_story_5032_50321101_63_dialog_content = "You also said you would make things up to me before, remember?",
  ui_story_5032_50321101_64_dialog_content = "Once the dust settles, I plan on collecting in full... So be ready for it.",
  ui_story_5032_50321101_65_dialog_content = "My ship is in desperate need of repairs, and you're going to be responsible for making it seaworthy again.",
  ui_story_5032_50321101_66_dialog_content = "I may be a magician, but I promise not to mislead you about the cost of repairs. In fact, I'll have Rainbow draw up an itemized list to make everything perfectly clear. All you need to do is have your wallet ready.",
  ui_story_5032_50321101_67_dialog_content = "I see... That shouldn't be a problem...",
  ui_story_5032_50321101_68_dialog_content = "Also, since we have no way of continuing our tour, we'll be staying in Harbor City for a while longer.",
  ui_story_5032_50321101_69_dialog_content = "In the meantime, we can try building that art restaurant that we used to talk about.",
  ui_story_5032_50321101_70_dialog_content = "Who knows? Maybe it can serve as our venue for future performances?",
  ui_story_5032_50321101_71_dialog_content = "Besides, someone of your status shouldn't have any trouble constructing a restaurant here...",
  ui_story_5032_50321101_72_dialog_content = "Jeno...",
  ui_story_5032_50321101_73_dialog_content = "Yeah? I'm here, Elvis.",
  ui_story_5032_50321101_74_dialog_content = "The sky over Harbor City... is clearing up.",
  ui_story_5032_50321101_75_dialog_content = "This has always been... my favorite sight.",
  ui_story_5032_50321101_76_dialog_content = "<size=30>Could you perhaps... paint it for me someday?</size>",
  ui_story_5032_50321101_77_dialog_content = "Sure. I promise.",
  ui_story_5032_50321101_78_dialog_content = "Remember that painting you asked for last time? I finished it a long time ago... It's been hanging in my room all this time.",
  ui_story_5032_50321101_79_dialog_content = "But it might not be exactly what you wanted. After all, I had to rely entirely on memory to paint it.",
  ui_story_5032_50321101_80_dialog_content = "You can take a look for yourself later. If you don't like it, I can always paint you another one.",
  ui_story_5032_50321101_81_dialog_content = "...",
  ui_story_5032_50321101_82_dialog_content = "... Elvis?",
  ui_story_5032_50321101_83_dialog_content = "...",
  ui_story_5032_50321101_84_dialog_content = "Tch... You're something else, you know that?",
  ui_story_5032_50321101_85_dialog_content = "Always make promises you can't keep...",
  ui_story_5032_50321101_86_dialog_content = "You're such a liar, Elvis...",
  ui_story_5032_50321101_87_dialog_content = "A good-for-nothing liar...",
  ui_story_5032_50321101_88_dialog_content = "<color=#e8d9bb>Five Days Later</color>",
  ui_story_5032_50321101_89_dialog_content = "*Sigh*",
  ui_story_5032_50321101_90_dialog_content = "It looks like you forgot your clothes, PlayerName. Someone came by and dropped them off.",
  ui_story_5032_50321101_91_dialog_content = "Y-You're right, I almost forgot to pack them! Thanks, Vice!",
  ui_story_5032_50321101_92_dialog_content = "Carleen's decision to go home came as a surprise, so in my rush to pack everything up, I nearly missed a few things.",
  ui_story_5032_50321101_93_dialog_content = "*Sigh*",
  ui_story_5032_50321101_94_dialog_content = "Why don't you take another look around and make sure you don't forget anything else? Carleen is still meeting with the city's officials, so you have time for one last check.",
  ui_story_5032_50321101_95_dialog_content = "Sure, I'll go take a look.",
  ui_story_5032_50321101_96_dialog_content = "*Sigh*",
  ui_story_5032_50321101_97_dialog_content = "... What's wrong, Fia?",
  ui_story_5032_50321101_98_dialog_content = "Is something on your mind, Fia? You've been frowning ever since we got up this morning.",
  ui_story_5032_50321101_99_dialog_content = "I'm just thinking about how Geedo left us so suddenly...",
  ui_story_5032_50321101_100_dialog_content = "How am I supposed to explain this to my master?!",
  ui_story_5032_50321101_101_dialog_content = "Lo...",
  ui_story_5032_50321101_102_dialog_content = "Your master should be able to sense Geedo's presence again, don't you think?",
  ui_story_5032_50321101_103_dialog_content = "I'm certain he noticed it the moment you freed Geedo from the bottle.",
  ui_story_5032_50321101_104_dialog_content = "You don't understand, Vice... If I don't show him proof to his face that my mission is complete, he won't pay up!",
  ui_story_5032_50321101_105_dialog_content = "He'll pretend as though I'm lying, and all of the rewards he promised me for a job well done... He'll throw them all away!",
  ui_story_5032_50321101_106_dialog_content = "Sounds like a fair and equitable relationship to me, Fia.",
  ui_story_5032_50321101_107_dialog_content = "That's enough out of you, PlayerName!",
  ui_story_5032_50321101_108_dialog_content = "Fia's master does sound a little excessive, don't you think?",
  ui_story_5032_50321101_109_dialog_content = "What should we do, PlayerName? Think we can take Fia with us and fly her home on Soroz?",
  ui_story_5032_50321101_110_dialog_content = "That way, we can act as her witnesses.",
  ui_story_5032_50321101_111_dialog_content = "Sounds good to me!",
  ui_story_5032_50321101_112_dialog_content = "H-Huh? Really?! That will be great!",
  ui_story_5032_50321101_113_dialog_content = "Thank you so much, Vice! This time, I'll make master pay every bit of what he owes me! Muahahaha!",
  ui_story_5032_50321101_114_dialog_content = "You three seem to be in pretty high spirits, eh?",
  ui_story_5032_50321101_115_dialog_content = "Ah! Did I just hear Subli's voice?",
  ui_story_5032_50321101_116_dialog_content = "Hiya!",
  ui_story_5032_50321101_117_dialog_content = "Rainbow told us you were heading out, so we wanted to send you off ourselves!",
  ui_story_5032_50321101_118_dialog_content = "...",
  ui_story_5032_50321101_119_dialog_content = "Safe travels, everyone!",
  ui_story_5032_50321101_120_dialog_content = "Come see our show the next time you have a chance! I'll snag you a good deal on primo seats!",
  ui_story_5032_50321101_121_dialog_content = "Hahaha! We might just take you up on that offer!",
  ui_story_5032_50321101_122_dialog_content = "Hey... I don't see Ciel anywhere. She didn't come with you, Rainbow?",
  ui_story_5032_50321101_123_dialog_content = "Ciel received an emergency summons from Illumina yesterday. She left in a real hurry, too.",
  ui_story_5032_50321101_124_dialog_content = "I see... Ciel sure does keep busy, doesn't she? They even called her back from her vacation...",
  ui_story_5032_50321101_125_dialog_content = "We were supposed to start repairs on the Emerald today...",
  ui_story_5032_50321101_126_dialog_content = "But Merylt practically begged for one last chance to see the Caelestite, so that's why...",
  ui_story_5032_50321101_127_dialog_content = "Ow!",
  ui_story_5032_50321101_128_dialog_content = "F-Frimet!",
  ui_story_5032_50321101_129_dialog_content = "Hahahaha! Looks like you've got yourself a diehard fan, PlayerName.",
  ui_story_5032_50321101_130_dialog_content = "That's right!",
  ui_story_5032_50321101_131_dialog_content = "Honestly... I mean, what's so great about PlayerName anyways?",
  ui_story_5032_50321101_132_dialog_content = "What about me? I also helped out a lot, you know! And Kyllo helped you guys find your three-tailed cat, too!",
  ui_story_5032_50321101_133_dialog_content = "You're absolutely right, Fia... Kyllo deserves our gratitude, as well!",
  ui_story_5032_50321101_134_dialog_content = "Isn't that right, Kyllo?",
  ui_story_5032_50321101_135_dialog_content = "Lo!",
  ui_story_5032_50321101_136_dialog_content = "Wh-What?!",
  ui_story_5032_50321101_137_dialog_content = "That does it, Frimet! I'm gonna show you just how strong I am!",
  ui_story_5032_50321101_138_dialog_content = "Oh my... Is that all it takes to get you worked up?",
  ui_story_5032_50321101_139_dialog_content = "Hehehe, looks like Fia made new friends, too.",
  ui_story_5032_50321101_140_dialog_content = "It sure does look that way. I'm so happy for them!",
  ui_story_5032_50321101_141_dialog_content = "Frimet and her sisters spend most of their days interacting with audience members... They rarely have the opportunity to talk to others outside of that capacity.",
  ui_story_5032_50321101_142_dialog_content = "As a result, they don't really have any friends their age.",
  ui_story_5032_50321101_143_dialog_content = "They're so lucky to have met someone like Fia...",
  ui_story_5032_50321101_144_dialog_content = "As well as the rest of you. We're all so fortunate to have made friends like you!",
  ui_story_5032_50321101_145_dialog_content = "*Sobbing* Rainbow...",
  ui_story_5032_50321101_146_dialog_content = "We're the ones who are lucky to have met you all, Rainbow!",
  ui_story_5032_50321101_147_dialog_content = "Heehee!",
  ui_story_5032_50321101_148_dialog_content = "Say, have any of you seen Carleen around?",
  ui_story_5032_50321101_149_dialog_content = "Carleen should still be meeting with the members of House Modali. We've been waiting here for her to finish up her business.",
  ui_story_5032_50321101_150_dialog_content = "So much has happened, after all... I'm sure there are plenty of matters that require her attention right now.",
  ui_story_5032_50321101_151_dialog_content = "<size=30>So this is the life of a princess, huh... So cool!</size>",
  ui_story_5032_50321101_152_dialog_content = "Hmm? Did you say something?",
  ui_story_5032_50321101_153_dialog_content = "Ehehe... You shouldn't ask a girl so many questions, PlayerName!",
  ui_story_5032_50321101_154_dialog_content = "Just mind your own business, okay?!",
  ui_story_5032_50321101_155_dialog_content = "Waah!",
  ui_story_5032_50321101_156_dialog_content = "C-Careful, Merylt!",
  ui_story_5032_50321101_157_dialog_content = "Seriously, what do you think you're doing, Subli?",
  ui_story_5032_50321101_158_dialog_content = "Hey, she is just trying to help out her sister in her own way! Hahaha!",
  ui_story_5032_50321101_159_dialog_content = "Do your best, Merylt!",
  ui_story_5032_50321101_160_dialog_content = "Eh? Rainbow—?",
  ui_story_5032_50321101_161_dialog_content = "S-S-Sorry about th-that!",
  ui_story_5032_50321101_162_dialog_content = "It's okay, Merylt. The only reason you bumped into me is that Subli shoved you just now.",
  ui_story_5032_50321101_163_dialog_content = "It didn't hurt at all, honest!",
  ui_story_5032_50321101_164_dialog_content = "...",
  ui_story_5032_50321101_165_dialog_content = "(This... This is my last chance!)",
  ui_story_5032_50321101_166_dialog_content = "U-Um...",
  ui_story_5032_50321101_167_dialog_content = "I-I wrote you a l-letter, PlayerName.",
  ui_story_5032_50321101_168_dialog_content = "Huh? A letter?",
  ui_story_5032_50321101_169_dialog_content = "P-Please don't open it until after you leave!",
  ui_story_5032_50321101_170_dialog_content = "Sure, no problem... Thank you!",
  ui_story_5032_50321101_171_dialog_content = "A-Also...",
  ui_story_5032_50321101_172_dialog_content = "Is there something else?",
  ui_story_5032_50321101_173_dialog_content = "I-If it's not too much t-trouble... May I...",
  ui_story_5032_50321101_174_dialog_content = "<size=30>M-May I...</size>",
  ui_story_5032_50321101_175_dialog_content = "I'm sorry, what was that?",
  ui_story_5032_50321101_176_dialog_content = "<size=45>May I visit you in Eraveil someday?!</size>",
  ui_story_5032_50321101_177_dialog_content = "Wow! Y-You scared me just now!",
  ui_story_5032_50321101_178_dialog_content = "I-I'm sorry! Was it weird of me to ask that?",
  ui_story_5032_50321101_179_dialog_content = "I-I totally understand if it's not okay! You can just say so, and I won't bother you ever again!",
  ui_story_5032_50321101_180_dialog_content = "I'm so sorry, I knew asking you would just make more trouble...",
  ui_story_5032_50321101_181_dialog_content = "Sure!",
  ui_story_5032_50321101_182_dialog_content = "Huh?",
  ui_story_5032_50321101_183_dialog_content = "Of course, you can come to see me anytime! We're friends, aren't we, Merylt?",
  ui_story_5032_50321101_184_dialog_content = "If you ever want to visit Eraveil, the door's always open. You can even bring some of your friends if you like!",
  ui_story_5032_50321101_185_dialog_content = "The reconstruction has been coming along nicely, so I'm sure there are plenty of rooms for you to stay in.",
  ui_story_5032_50321101_186_dialog_content = "F-Friends...?",
  ui_story_5032_50321101_187_dialog_content = "... Th-Thank you!",
  ui_story_5032_50321101_188_dialog_content = "Now that you mention it, I should probably stop by Umbraton on the way back.",
  ui_story_5032_50321101_189_dialog_content = "If we want to welcome any guests, we probably need to stock up on some food. We're nearly out of herbicide for the weeds, too...",
  ui_story_5032_50321101_190_dialog_content = "We're also running low on washing powder and a bunch of other daily necessities... Hmmm...",
  ui_story_5032_50321101_191_dialog_content = "We'll need some supplies to help us beat the heat, as well...",
  ui_story_5032_50321101_192_dialog_content = "(Frimet, Subli, I think...)",
  ui_story_5032_50321101_193_dialog_content = "(I think I know why I like this Caelestite so much now.)",
  ui_story_5032_50321101_194_dialog_content = "Frimet... She's as slippery as an eel in a bucket of oil!",
  ui_story_5032_50321101_195_dialog_content = "Well, she is a trained circus performer, after all...",
  ui_story_5032_50321101_196_dialog_content = "Urgh... I won't go so easy on her next time! I swear it!",
  ui_story_5032_50321101_197_dialog_content = "Lo!",
  ui_story_5032_50321101_198_dialog_content = "Sorry to have kept you all waiting.",
  ui_story_5032_50321101_199_dialog_content = "It seems I missed out on a lot of the fun.",
  ui_story_5032_50321101_200_dialog_content = "Carleen! You're back!",
  ui_story_5032_50321101_201_dialog_content = "You didn't miss much, just Frimet making a total fool out of Fia... Ouch!",
  ui_story_5032_50321101_202_dialog_content = "That really hurt! Quit stomping on my foot!",
  ui_story_5032_50321101_203_dialog_content = "Hmph! That'll teach you to make fun of me, PlayerName.",
  ui_story_5032_50321101_204_dialog_content = "Alright, everyone, that's enough for now.",
  ui_story_5032_50321101_205_dialog_content = "Has everything been taken care of on your side, Carleen?",
  ui_story_5032_50321101_206_dialog_content = "*Sigh* You can say that, yes.",
  ui_story_5032_50321101_207_dialog_content = "I couldn't come to an agreement with Loewe and Matthieu on how best to proceed. Frustrating as it has been, they no longer wish to keep everything a secret.",
  ui_story_5032_50321101_208_dialog_content = "They received my itinerary this morning and returned to Lumopolis.",
  ui_story_5032_50321101_209_dialog_content = "Father was quite displeased when I previously deceived him... I still have to figure out what I'm going to say to him when I return.",
  ui_story_5032_50321101_210_dialog_content = "That's right... you were basically hiding the truth from Lord Schwartz for the sake of Harbor City.",
  ui_story_5032_50321101_211_dialog_content = "Fortunately, Matthieu and the others don't know much about the Windstone.",
  ui_story_5032_50321101_212_dialog_content = "At the very least, that's one less thing to worry about.",
  ui_story_5032_50321101_213_dialog_content = "House Modali is in complete disarray right now... They still need to appoint a new laird, as well.",
  ui_story_5032_50321101_214_dialog_content = "If word gets out about the Windstone, they'll never be able to handle things.",
  ui_story_5032_50321101_215_dialog_content = "Then...",
  ui_story_5032_50321101_216_dialog_content = "Does that mean Elvis still hasn't shown any sign of waking up?",
  ui_story_5032_50321101_217_dialog_content = "Indeed. Currently, he is still in a deep coma.",
  ui_story_5032_50321101_218_dialog_content = "If it wasn't for Jeno helping him bear the load for reactivating the Windstone, Elvis would already be dead.",
  ui_story_5032_50321101_219_dialog_content = "However, even the best doctors have no way of waking him from a coma like this.",
  ui_story_5032_50321101_220_dialog_content = "*Sigh* It's so sad to see him like that, and after all of the battles he's lived through...",
  ui_story_5032_50321101_221_dialog_content = "Maybe... this is Elvis' fate?",
  ui_story_5032_50321101_222_dialog_content = "Elvis' desire to protect his people led to this disaster in the first place.",
  ui_story_5032_50321101_223_dialog_content = "And so, the only way to save his people from his own wrongdoing was to sacrifice himself.",
  ui_story_5032_50321101_224_dialog_content = "In a way, you can say that he accomplished what he set out to do from the very beginning.",
  ui_story_5032_50321101_225_dialog_content = "Someone like him must have already made peace with this as a possible outcome.",
  ui_story_5032_50321101_226_dialog_content = "...",
  ui_story_5032_50321101_227_dialog_content = "Incredible... You always manage to speak so well when it matters most, Fia.",
  ui_story_5032_50321101_228_dialog_content = "I can't help but admire you a little more after saying that.",
  ui_story_5032_50321101_229_dialog_content = "Whaaaaat? You mean you couldn't come to such a simple conclusion on your own, PlayerName?",
  ui_story_5032_50321101_230_dialog_content = "You won't last a day in society if you don't start thinking for yourself a little more, you know!",
  ui_story_5032_50321101_231_dialog_content = "I was just paying you a compliment! Don't let it go to your head!",
  ui_story_5032_50321101_232_dialog_content = "Keep this up, and I might change my mind about helping you explain things to your master!",
  ui_story_5032_50321101_233_dialog_content = "Wh-What?! No, please! Anything but that!",
  ui_story_5032_50321101_234_dialog_content = "You already promised to help! What kind of person would you be if you didn't keep your promises?!",
  ui_story_5032_50321101_235_dialog_content = "Fia does make a good point, you know.",
  ui_story_5032_50321101_236_dialog_content = "This might just be the outcome that Elvis wished for the most.",
  ui_story_5032_50321101_237_dialog_content = "Peace has finally returned to Harbor City, after all.",
  ui_story_5032_50321101_238_dialog_content = "It's just sad that despite all of his hard work and sacrifice, the Modali Syndrome is still a problem.",
  ui_story_5032_50321101_239_dialog_content = "Actually, this is one matter that doesn't require too much concern, at least for the time being.",
  ui_story_5032_50321101_240_dialog_content = "Jeno told me that the Windstone seems to have absorbed a large amount of the Cloudwhale's Lumina during the last battle.",
  ui_story_5032_50321101_241_dialog_content = "As a result, the Windstone is prioritizing using the Cloudwhale's purer Lumina to protect Harbor City from Eclipsite attacks.",
  ui_story_5032_50321101_242_dialog_content = "Really? That's amazing!",
  ui_story_5032_50321101_243_dialog_content = "If that's true, then Elvis' sacrifice wasn't in vain at all!",
  ui_story_5032_50321101_244_dialog_content = "That reminds me, I haven't seen Jeno at all lately.",
  ui_story_5032_50321101_245_dialog_content = "Is he okay?",
  ui_story_5032_50321101_246_dialog_content = "Elvis' condition has caused him no small amount of distress... He even lost some weight from worrying.",
  ui_story_5032_50321101_247_dialog_content = "But when I saw him yesterday, he seemed to have regained his usual composure.",
  ui_story_5032_50321101_248_dialog_content = "I found it!",
  ui_story_5032_50321101_249_dialog_content = "I think I found a way to wake him up again!",
  ui_story_5032_50321101_250_dialog_content = "What?",
  ui_story_5032_50321101_251_dialog_content = "Forgive me, Princess Carleen...",
  ui_story_5032_50321101_252_dialog_content = "But I have to go... I need to go find it right away!",
  ui_story_5032_50321101_253_dialog_content = "So he really found a way to awaken Elvis from his coma?",
  ui_story_5032_50321101_254_dialog_content = "Perhaps.",
  ui_story_5032_50321101_255_dialog_content = "But even if he succeeds in awakening Elvis, this won't save him from facing Lumopolis' judgment.",
  ui_story_5032_50321101_256_dialog_content = "Ironically enough, his comatose state is the only thing keeping him from his punishment.",
  ui_story_5032_50321101_257_dialog_content = "Even so, I can understand Jeno's feelings.",
  ui_story_5032_50321101_258_dialog_content = "If something like that happened to Carleen, Vice, Fia, or Kyllo...",
  ui_story_5032_50321101_259_dialog_content = "I'm sure the rest of us would stop at nothing to find a way to save them.",
  ui_story_5032_50321101_260_dialog_content = "You make a good point too!",
  ui_story_5032_50321101_261_dialog_content = "We're all dear friends, after all.",
  ui_story_5032_50321101_262_dialog_content = "Indeed... you are right, PlayerName.",
  ui_story_5032_50321101_263_dialog_content = "Anyways, it's starting to get late. We should really get going.",
  ui_story_5032_50321101_264_dialog_content = "We have plenty of stops to make. Umbraton, Lumopolis... and Fia's master's house, as well.",
  ui_story_5032_50321101_265_dialog_content = "We have a full trip ahead of us, huh?",
  ui_story_5032_50321101_266_dialog_content = "Yep, now let's get moving!",
  ui_story_5032_50321101_267_dialog_content = "Off we go! I wanna buy some stuff in Umbraton too!",
  ui_story_5032_50321101_268_dialog_content = "PlayerName, you promised to buy me a hand-tailored swimsuit too!",
  ui_story_5032_50321101_269_dialog_content = "... You haven't forget about it after everything?!"
}
